type Result = NerfGame["result"];

// Replay compatibility version, stamped on every new match. Bump it whenever
// an engine constant that feeds the deterministic replay changes (draft
// cadence, boon/card pools, offer rolling): a stored game recorded under
// different constants replays into a different stream of offers, so its
// recorded picks no longer line up and moveByUci fails mid-replay. On load,
// a started match whose stored replayVersion differs from this constant is
// ended gracefully as a draw ("server update interrupted this game") through
// the normal end flow: never silently deleted, never soft-locked.
// Version history:
//   1 (implicit) - matches stored before the field existed. They carry no
//     version to compare, so replay FAILURE is their trigger: if their
//     replay still succeeds under the current constants they play on
//     untouched; if it fails they get the same graceful draw ending.
//   2 - draft cadence moved from 10 to 6 and the nerf-mode boon pool
//     changed. From here on, a version MISMATCH is the trigger for started
//     draft games (their replay is known-desynced even when it happens not
//     to throw).
//   3 - hexes and items joined the pools: nerf mode now drafts opponent
//     hexes (60/40 weighted bucket roll inside rollOffer consumes an extra
//     RNG draw per card), items joined both modes, and the opening nerf
//     deal is capped at tier 2.
const REPLAY_VERSION = 3;

type Setup = {
  whiteNerfId: string;
  blackNerfId: string;
  seed: number;
  timeSec: number;
  incrementSec: number;
};
type SeatUser = { id: string; name: string; rating: number; rd?: number; vol?: number; avatar?: string | null };
type ChatEntry = { color: Color; name: string; text: string; at: number };
// Spectator-room chat: watchers only, players never see it.
type SpectatorChatEntry = { name: string; text: string; at: number };
// One resolved draft interaction, stored in order. `ply` is the number of
// accepted moves at the moment the action happened, so replaying moves and
// actions interleaved through the engine rebuilds the exact game state
// (board mutations, RNG stream, and all) on reconnects and DO restarts.
type StoredDraftAction =
  | { ply: number; color: Color; a: "pick"; index: number; cards: { id: string; tier: number }[] }
  | { ply: number; color: Color; a: "bank" }
  | { ply: number; color: Color; a: "use"; buffIndex: number; picks: BuffPick[] };
type StoredMatch = {
  id: string;
  setup: Setup;
  tokens: Record<Color, string>;
  disconnectedAt: Partial<Record<Color, number>>;
  opponentGoneNotified: Partial<Record<Color, boolean>>;
  moves: string[];
  result: Result;
  clocks: Record<Color, number>;
  runningSince: number | null;
  drawOfferBy: Color | null;
  // Pending takeback request (casual games only).
  takebackOfferBy?: Color | null;
  createdAt: number;
  startedAt: number | null;
  completedAt: number | null;
  // Rated matchmade games carry the two accounts; friend games may carry them
  // too (for history) but stay casual.
  rated?: boolean;
  users?: Partial<Record<Color, SeatUser>>;
  recorded?: boolean;
  // Matchmade and rematch games start automatically once both seats connect
  // (friend games wait in the lobby for a join instead).
  autoStart?: boolean;
  // Direct challenge: only this username may join as black. Never listed as
  // an open challenge in the lobby.
  invitedUsername?: string;
  rematchOfferBy?: Color | null;
  // Set once a rematch match has been created from this one.
  rematchedTo?: string | null;
  chat?: ChatEntry[];
  spectatorChat?: SpectatorChatEntry[];
  // Colors that voluntarily revealed their rule to the table mid-game.
  revealed?: Partial<Record<Color, boolean>>;
  // Draft ruleset games. Friend/challenge Draft matches are always casual:
  // createMatch never honors a rated request. Queue Draft matches are rated
  // under their mode's rating bucket (see queueJoin).
  draft?: boolean;
  // Which section the draft game runs under: "nerf" (opening nerf pick,
  // nerf-modifier buffs only, slow cadence) or "buff" (no nerfs at all,
  // nerf-modifier buffs excluded). Absent = legacy merged rules, kept so
  // stored games replay unchanged.
  mode?: DraftMode;
  // Friend-game setting: both seats see each other's pending offer cards.
  picksVisible?: boolean;
  // "Surprise / Stacked draft" preset: the joining friend (black seat) drafts
  // with a persistent tier lift on every offer, so they receive a strong,
  // high-tier build. Casual only. Persisted so the boost replays identically.
  stacked?: boolean;
  // Replay compatibility stamp (see REPLAY_VERSION). Absent = version 1.
  replayVersion?: number;
  // Draft cadence the game was created under, persisted so replays keep
  // using it even after the engine default changes.
  cadence?: number;
  // Seed for the draft engine RNG (offer rolls). Never sent to any client:
  // it would let a client predict every future offer.
  draftSeed?: number;
  // Moderator card overrides that shape this game's draft pools (disabled
  // buff ids and tier moves), frozen at match creation. Replays re-roll
  // offers and resolve recorded pick indexes against them, so the snapshot
  // must never change over the life of a match. Absent = no overrides.
  cardOverrides?: DraftPoolOverrides;
  draftActions?: StoredDraftAction[];
  // Opening nerf draft (Draft games only). Dealt when the second seat
  // arrives; the match stays un-started (clocks off, moves rejected) until
  // both seats have picked. Options are public to both seats; each pick's
  // identity follows the usual reveal rules.
  nerfOptions?: Record<Color, string[]>;
  nerfPicks?: Partial<Record<Color, number>>;
  // Lock-in deadlines (ms epoch). The opening nerf draft and any pending
  // buff offers auto-resolve when these pass; clocks stay paused meanwhile.
  nerfDeadline?: number | null;
  dtDeadline?: number | null;
  // Draft games: the side actually to move. Buff activations consume the
  // activator's turn and tempo cards insert extra moves or skips, so move
  // parity no longer determines it. Classic games never set this.
  turnColor?: Color;
  // House-player seats: color -> house user id (see lib/server/bots.ts). A
  // house seat counts as connected for game start; the alarm plays its moves
  // and draft picks. Absent on every purely human game.
  bots?: Partial<Record<Color, string>>;
  // When the next pending house action (move, opening nerf pick, or buff
  // offer resolve) lands. Null/absent when no house action is pending.
  botActAt?: number | null;
};
