// life, because recorded draft picks replay against re-rolled offers and a
// pool that shifted mid-match would desync them.
const cardOverridesTtlMs = 5 * 60 * 1000;
// The DO-side digest of card_overrides: only the fields that shape pools.
// Name/description/flavor overrides are display-only and never reach here.
type CardOverridesSnapshot = {
  /** Buff-card ids removed from draft pools (enabled = 0). */
  buffOff?: string[];
  /** Buff-card id -> overridden tier (1-8, differs from the code tier). */
  buffTier?: Record<string, number>;
  /** Nerf ids removed from opening deals (dealt pairs and the nerf draft). */
  nerfOff?: string[];
};
// Lichess-style start-of-game grace: a player's clock only starts charging 10
// seconds into their first move, so nobody loses time to a slow page load.
const firstMoveGraceMs = 10 * 1000;
// Draft lock-in window: every pick (the opening nerf pick and each buff
// offer) must resolve within this window while the game clock is paused.
// The server auto-resolves overdue picks so a stalling player cannot freeze
// the game.
const draftLockInMs = 20 * 1000;
// Grace after a lock-in deadline before the server force-resolves it. A pick
// the player clicked right at the deadline arrives a network hop later; without
// this the auto-resolve fires first (defaulting the opening nerf pick to option
// 0) and the real pick is then rejected as "no nerf draft". Clocks are paused
// during the nerf draft, so this grace costs neither player any time.
const draftPickGraceMs = 2 * 1000;

function randomInt(max: number): number {
  const values = new Uint32Array(1);
  crypto.getRandomValues(values);
  return values[0] % max;
}

function randomCode(length = 5): string {
  const chars = "BCDFGHJKMNPQRSTVWXYZ23456789";
  let code = "";
  for (let i = 0; i < length; i++) code += chars[randomInt(chars.length)];
  return code;
}

function newToken(): string {
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  return [...bytes].map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

function makeSeed(): number {
  return randomInt(2 ** 31);
}

// Deal the two secret rules for a new match, honoring moderator-disabled
// nerfs (card_overrides). When the disable list would leave a degenerate pool
// the full opening pool deals instead: a playable game beats the filter.
function pickNerfIds(disabledNerfIds?: string[]): { whiteNerfId: string; blackNerfId: string } {
  if (disabledNerfIds && disabledNerfIds.length > 0) {
    const off = new Set(disabledNerfIds);
    const pool = openingNerfPool().filter((nerf) => !off.has(nerf.id));
    if (pool.length >= 2) return pickNerfPair(randomInt, pool);
  }
  return pickNerfPair(randomInt);
}

function isColor(value: unknown): value is Color {
  return value === "w" || value === "b";
}

function matchKey(id: string): string {
  return `match:${id}`;
}

function send(ws: WebSocket | undefined, t: string, d?: unknown) {
  if (!ws || ws.readyState !== WebSocket.OPEN) return;
  ws.send(JSON.stringify(d === undefined ? { t } : { t, d }));
}

function error(ws: WebSocket, code: string, message: string) {
  send(ws, "error", { code, message });
}

// House-bot engine offload (see docs/bot-offload-tier1-engine-service.md).
// When HOUSE_ENGINE_REMOTE === "true" the house move search runs on the OCI
// box instead of this single-threaded DO. The fetch is hard-bounded so a slow
// or unreachable box can never stall the alarm tick — on timeout/failure the
// bot falls back to the local engine (full strength), never to nothing.
//
// This is a WALL-clock bound on an awaited fetch, so it costs the DO no CPU
// while waiting — it must clear the real round-trip to the engine or the
// offload silently no-ops and every bot move runs its search locally on the DO
// (the CPU spike this offload exists to avoid). The engine lives in Tokyo behind
// Cloudflare; the observed round-trip is ~500ms, so 150ms aborted every call.
// 3000ms comfortably clears RTT + engine search; bots are meant to pace their
// moves, so the extra latency is harmless.
const HOUSE_ENGINE_TIMEOUT_MS = 3000;

