// Bootstrap state for a spectator's wstart, pushed by the arena for a watched,
// started game (Tier 2 / M3). Mirrors arena-service ArenaSnapshot.
type ArenaSnapshot = {
  id: string;
  setup: { whiteNerfId: string; blackNerfId: string; seed: number; timeSec: number; incrementSec: number };
  mode: DraftMode;
  draft: true;
  draftSeed: number;
  cadence: number;
  moves: string[];
  draftActions: StoredDraftAction[];
  clocks: Record<Color, number>;
  startedAt: number;
  seats: Record<Color, ExternalSeat>;
};

// One spectator event the arena pushes for a watched game (Tier 2 / M3). The DO
// advances its ephemeral replica and relays the matching frame to that game's
// watchers. Mirrors arena-service ArenaFrame.
type ArenaFrame =
  | ({ kind: "snapshot" } & ArenaSnapshot)
  | { kind: "move"; id: string; ply: number; u: string; clocks: Record<Color, number> }
  | { kind: "draft"; id: string; action: StoredDraftAction; card?: { id: string; tier: number } };

// Move equality for validating a move returned by the remote engine against
// our own legal-move set. UCI (from+to+promotion) is not enough: buff-generated
// moves share a UCI with a normal move to the same square, so `via` is part of
// the identity.
function sameMove(a: Move, b: Move): boolean {
  return (
    a.from === b.from &&
    a.to === b.to &&
    (a.promotion ?? null) === (b.promotion ?? null) &&
    (a.via ?? null) === (b.via ?? null)
  );
}

// The StoredMatch subset the remote engine needs to replay the position.
// Deliberately omits clocks, sessions, tokens, users — nothing but the record
// the engine replays.
function serializeMatchForEngine(match: StoredMatch): EngineMatch {
  return {
    setup: {
      whiteNerfId: match.setup.whiteNerfId,
      blackNerfId: match.setup.blackNerfId,
      seed: match.setup.seed,
    },
    mode: match.mode,
    draft: match.draft,
    draftSeed: match.draftSeed,
    cadence: match.cadence,
    stacked: match.stacked,
    moves: match.moves,
    draftActions: match.draftActions,
  };
}

export class GameServer extends DurableObject<Env> {
  private sessions = new Map<WebSocket, SessionAttachment>();
  private dbReady: Promise<boolean> | null = null;
  // Short-lived in-memory cache of the assembled lobby snapshot. Every client
  // polls the lobby roughly every 5s and each rebuild does a full match scan on
  // this single-threaded DO, so concurrent polls serialize behind the scan.
  // Caching the shared (public) snapshot for a couple of seconds collapses that
  // burst into one scan. Cleared whenever the match set changes (saveMatch /
  // deleteMatch); queue/seek changes are absorbed by the TTL.
  private lobbyCache: { at: number; payload: unknown } | null = null;
  private static readonly LOBBY_CACHE_TTL_MS = 2000;
  // Arena (Tier 2 / M2): bot-vs-bot games simulated on the OCI arena, kept in
  // memory only. Refreshed by /arena/games; entries older than the TTL are
  // ignored (self-heals if the arena crashes or the DO loses this on eviction).
  private externalGames = new Map<string, { meta: ExternalGameMeta; at: number }>();
  // Arena game ids already archived, so a retried /arena/end never double-rates
  // the house accounts. In-memory + bounded; the rare eviction-window dup is
  // bot-only and low stakes.
  private arenaArchived = new Set<string>();
  // Tier 2 / M3 (spectating): an ephemeral StoredMatch replica for each arena
  // game a human is watching, built from the arena's snapshot and advanced by
  // its move/draft frames. Never persisted. Present only while watched, so the
  // per-move replay cost the DO pays for a bot game exists only when someone is
  // looking — dropped when the last spectator leaves or the game ends.
  private externalMatches = new Map<string, StoredMatch>();

  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    for (const ws of this.ctx.getWebSockets()) {
      const attachment = ws.deserializeAttachment() as SessionAttachment | null;
      if (attachment) this.sessions.set(ws, attachment);
    }
  }

  // Resolves to true when D1 is configured and its schema is in place.
  // Account features degrade to anonymous play when it isn't.
  private async db(): Promise<D1Database | null> {
    if (!this.env.DB) return null;
    if (!this.dbReady) {
      this.dbReady = ensureSchema(this.env.DB).then(
        () => true,
        () => false,
      );
    }
    return (await this.dbReady) ? this.env.DB : null;
  }

  // Runtime on/off for the house bots. Read from the shared app_settings table
  // (a moderator flips it via POST /api/mod/house) and cached briefly so the
  // alarm/seek paths do no per-tick D1 work. The HOUSE_ENABLED constant stays a
  // hard code-level kill switch that wins over the stored value. Missing row or
  // any read error defaults to ON, so the bots never vanish on a transient blip.
  private houseEnabledCache: { value: boolean; at: number } | null = null;
  private async houseEnabled(): Promise<boolean> {
    if (!HOUSE_ENABLED) return false;
    const now = Date.now();
    if (this.houseEnabledCache && now - this.houseEnabledCache.at < houseEnabledTtlMs) {
      return this.houseEnabledCache.value;
    }
    let value = true;
    try {
      const db = await this.db();
      if (db) {
        const row = await db
          .prepare("SELECT value FROM app_settings WHERE key = ?")
          .bind("house_enabled")
          .first<{ value: string }>();
        if (row) value = row.value !== "0" && row.value !== "false";
      }
    } catch {}
    this.houseEnabledCache = { value, at: now };
    return value;
  }

  // Moderator card overrides (the card_overrides table), digested down to the
  // fields that shape pools: disabled buff/nerf ids and buff tier moves. One
  // bounded SELECT (the table holds at most one row per card), cached for
  // cardOverridesTtlMs and refreshed only from match creation and the opening
  // nerf deal: never per message or per alarm tick. Any read error keeps the
  // previous snapshot (or none), so a D1 blip can never block games.
  private cardOverridesCache: { value: CardOverridesSnapshot; at: number } | null = null;
  private async cardOverridesSnapshot(): Promise<CardOverridesSnapshot> {
    const now = Date.now();
    if (this.cardOverridesCache && now - this.cardOverridesCache.at < cardOverridesTtlMs) {
      return this.cardOverridesCache.value;
    }
    let value: CardOverridesSnapshot = this.cardOverridesCache?.value ?? {};
    try {
      const db = await this.db();
      if (db) {
        const { results } = await db
          .prepare(
            "SELECT id, kind, tier, enabled FROM card_overrides WHERE enabled = 0 OR tier IS NOT NULL",
          )
          .all<{ id: string; kind: string; tier: number | null; enabled: number }>();
        const next: CardOverridesSnapshot = {};
        for (const row of results ?? []) {
          if (row.kind === "buff") {
            const def = BUFF_BY_ID[row.id];
            if (!def) continue;
            if (!row.enabled) {
              (next.buffOff ??= []).push(row.id);
            } else if (
              row.tier != null &&
              Number.isInteger(row.tier) &&
              row.tier >= 1 &&
              row.tier <= 8 &&
              row.tier !== def.tier
            ) {
              (next.buffTier ??= {})[row.id] = row.tier;
            }
          } else if (row.kind === "nerf" && !row.enabled) {
            (next.nerfOff ??= []).push(row.id);
          }
        }
        value = next;
      }
    } catch {}
    this.cardOverridesCache = { value, at: now };
    return value;
  }

  // The buff-pool slice of the snapshot, in the shape stamped onto new draft
  // matches (StoredMatch.cardOverrides). Undefined when there is nothing to
  // apply, so untouched deployments keep byte-identical match records.
  private draftPoolStamp(snap: CardOverridesSnapshot): DraftPoolOverrides | undefined {
    const off = snap.buffOff ?? [];
    const tier = snap.buffTier ?? {};
    if (off.length === 0 && Object.keys(tier).length === 0) return undefined;
    return {
      ...(off.length > 0 ? { off: [...off] } : {}),
      ...(Object.keys(tier).length > 0 ? { tier: { ...tier } } : {}),
    };
  }

  // Top-level fetch: a thin guard around handleFetch so a transient storage
  // or accept throw returns a clean degraded response instead of rejecting at
  // the RPC boundary and 503-ing every request into this Durable Object.
  async fetch(request: Request): Promise<Response> {
    try {
      return await this.handleFetch(request);
    } catch (err) {
      console.error("game server fetch failed", err);
      let pathname = "";
      try {
        pathname = new URL(request.url).pathname;
      } catch {}
      if (pathname === "/healthz") {
        return Response.json(
          { ok: false, version: buildVersion, error: err instanceof Error ? `${err.name}: ${err.message}` : String(err) },
          { status: 200 },
        );
      }
      return new Response("game server unavailable", { status: 503 });
    }
  }

  private async handleFetch(request: Request): Promise<Response> {
    const url = new URL(request.url);

    if (url.pathname === "/healthz") {
      // Read-only diagnostics plus a cheap alarm-chain revival. Never run
      // orchestration here: driving engine searches from a request handler
      // blows the per-request CPU limit (learned the hard way, see the
      // retired system's history). Best-effort: a storage hiccup in the
      // revival or cleanup must not stop /healthz from returning diagnostics.
      // reviveAlarmChain is cheap (a getAlarm) and runs on every hit; the full
      // GC scan in cleanupExpired is NOT — throttle it so an uptime monitor
      // polling /healthz every few seconds cannot repeatedly trigger a
      // whole-table scan (plus delete writes) on the single thread.
      try {
        await this.reviveAlarmChain();
        const now = Date.now();
        if (now - this.lastHealthzCleanupAt >= maintenanceMinIntervalMs) {
          this.lastHealthzCleanupAt = now;
          await this.cleanupExpired();
        }
      } catch (err) {
        console.error("healthz maintenance failed", err);
      }

      // cleanupExpired above already ran (and refreshed) a full scan for GC;
      // reuse the live index for these counts via targeted reads instead of a
      // second whole-table deserialize on the single thread. "games" now
      // reports live (unfinished) games, which is the number that matters here.
      const liveMatches = await this.loadLiveMatches();
      const alarmAt = await this.ctx.storage.getAlarm();
      let houseGames = 0;
      let houseVsHouse = 0;
      for (const match of liveMatches) {
        const seats = (["w", "b"] as Color[]).filter((color) => match.bots?.[color]).length;
        if (!seats) continue;
        houseGames++;
        if (seats === 2) houseVsHouse++;
      }
      const seeks = (await this.ctx.storage.get<HouseSeekEntry[]>(houseSeeksKey)) ?? [];
      const seeded = !!(await this.ctx.storage.get<number>(houseSeededKey));

      return Response.json({
        ok: true,
        version: buildVersion,
        sockets: this.sessions.size,
        games: liveMatches.length,
        alarmAt, // ms epoch of the next scheduled maintenance pass, if any
        alarmInMs: alarmAt ? alarmAt - Date.now() : null,
        house: {
          roster: HOUSE_ROSTER.length,
          seeded,
          seeks: seeks.length,
          games: houseGames,
          houseVsHouse,
          tickError: this.houseTickError,
        },
      });
    }

    if (url.pathname.startsWith("/arena/")) return this.handleArena(request, url);

    if (url.pathname !== socketPath) return new Response("Not found", { status: 404 });
    if (request.headers.get("Upgrade") !== "websocket") {
      return new Response("Expected WebSocket", { status: 426 });
    }
    if (!this.originAllowed(request)) {
      return new Response("Forbidden", { status: 403 });
    }

    // Same-origin websocket upgrades carry the session cookie; attach the
    // account (if any) so queueing and rated games know who this socket is.
    const attachment: SessionAttachment = { id: crypto.randomUUID() };
    const db = await this.db();
    if (db) {
      try {
        const token = sessionTokenFromCookieHeader(request.headers.get("Cookie"));
        const user = await userForSession(db, token);
        if (user) {
          attachment.userId = user.id;
          attachment.username = user.username;
          if (user.muted_until && user.muted_until > Date.now()) {
            attachment.mutedUntil = user.muted_until;
          }
        }
      } catch {
        // Anonymous on any auth failure.
      }
    }

    const pair = new WebSocketPair();
    const [client, server] = Object.values(pair);
    server.serializeAttachment(attachment);
    this.sessions.set(server, attachment);
    try {
      this.ctx.acceptWebSocket(server);
    } catch (err) {
      // The accept itself failed (hibernation limit, transient platform
      // error). Drop the half-registered session and fail this one upgrade
      // cleanly instead of throwing out of fetch and 503-ing the isolate.
      this.sessions.delete(server);
      console.error("acceptWebSocket failed", err);
      return new Response("game server unavailable", { status: 503 });
    }

    // A connecting human revives a wedged alarm chain so the house roster
    // (and clock enforcement) always comes back after a bad deploy or crash.
    try {
      await this.reviveAlarmChain();
    } catch {}

    return new Response(null, { status: 101, webSocket: client });
  }

  async webSocketMessage(ws: WebSocket, message: ArrayBuffer | string) {
    let frame: ClientFrame;
    try {
      frame = JSON.parse(typeof message === "string" ? message : new TextDecoder().decode(message)) as ClientFrame;
    } catch {
      return error(ws, "bad_json", "Messages must be JSON objects.");
    }

    switch (frame.t) {
      case "create":
        return this.createMatch(ws, frame.d);
      case "join":
        return this.joinMatch(ws, frame.d);
      case "reconnect":
        return this.reconnectMatch(ws, frame.d);
      case "move":
        return this.playClientMove(ws, frame.d);
      case "resign":
        return this.resignGame(ws);
      case "claimWin":
        return this.claimAbandonment(ws, false);
      case "claimDraw":
        return this.claimAbandonment(ws, true);
      case "drawOffer":
        return this.offerDraw(ws);
      case "drawAccept":
        return this.acceptDraw(ws);
      case "drawDecline":
        return this.declineDraw(ws);
      case "takebackOffer":
        return this.offerTakeback(ws);
      case "takebackAccept":
        return this.acceptTakeback(ws);
      case "takebackDecline":
        return this.declineTakeback(ws);
      case "queue":
        return this.queueJoin(ws, frame.d);
      case "queueCancel":
        return this.queueLeave(ws, true);
      case "watch":
        return this.watchMatch(ws, frame.d);
      case "watchLeave":
        return this.watchLeave(ws);
      case "lobby":
        return this.lobbySnapshot(ws);
      case "rematch":
        return this.rematchRequest(ws);
      case "rematchCancel":
        return this.rematchCancel(ws);
      case "chat":
        return this.chatMessage(ws, frame.d);
      case "schat":
        return this.spectatorChatMessage(ws, frame.d);
      case "reveal":
        return this.revealRule(ws);
      case "dtPick":
        return this.draftPick(ws, frame.d);
      case "dtBank":
        return this.draftBank(ws);
      case "dtUse":
        return this.draftUse(ws, frame.d);
      case "dtTarget":
        return this.draftTarget(ws, frame.d);
      case "dtNerfPick":
        return this.nerfDraftPick(ws, frame.d);
      case "p":
        return this.sendClocks(ws);
      default:
        return error(ws, "unknown_message", "Unknown message type.");
    }
  }

  async webSocketClose(ws: WebSocket) {
    await this.queueLeave(ws, false);
    this.notifyWatcherCount(ws);
    await this.detachSession(ws);
  }

  async webSocketError(ws: WebSocket) {
    await this.queueLeave(ws, false);
    this.notifyWatcherCount(ws);
    await this.detachSession(ws);
  }

  // When a spectating socket goes away, tell the remaining watchers the new
  // count. Must run before the session is dropped from the map.
  private notifyWatcherCount(ws: WebSocket) {
    const session = this.sessions.get(ws);
    if (!session?.watching) return;
    const id = session.watching;
    this.sessions.delete(ws);
    this.broadcastWatchers(id);
    this.dropExternalIfUnwatched(id);
  }

  private watcherCount(matchId: string): number {
    return this.watcherInfo(matchId).n;
  }

  // Count plus the signed-in watchers' usernames (deduped across tabs);
  // anonymous watchers only contribute to the count.
  private watcherInfo(matchId: string): { n: number; names: string[] } {
    let n = 0;
    const names = new Set<string>();
    for (const [ws, session] of this.sessions) {
      if (session.watching === matchId && ws.readyState === WebSocket.OPEN) {
        n++;
        if (session.username) names.add(session.username);
      }
    }
    return { n, names: [...names].slice(0, 30) };
  }

  private broadcastWatchers(matchId: string) {
    const { n, names } = this.watcherInfo(matchId);
    for (const [ws, session] of this.sessions) {
      if (ws.readyState !== WebSocket.OPEN) continue;
      if (session.watching === matchId || session.matchId === matchId) {
        send(ws, "watchers", { n, names });
      }
    }
  }

  async alarm() {
    // Nothing in here may throw out of the handler: an uncaught alarm error
    // stops rescheduling until the next external event (no flag enforcement).
    // House work runs first (a queued human waiting for a pickup is the most
    // latency-sensitive thing here) but is fully isolated: any house failure
    // degrades to "bots absent", never to broken human play.
    //
    // Alarm-chain liveness is the single most important invariant here: the
    // reschedule happens via scheduleNextAlarm (at the tail of maintenanceAll,
    // or directly on a throttled in-between tick below), so if that throws
    // before rescheduling — or the isolate is evicted mid-tick by a CPU spike —
    // the chain would die until a socket reconnect and every house game plus
    // clock enforcement would freeze: exactly the "server is always crashing /
    // bot won't move" symptom. Guard it two ways: (1) a defensive floor alarm
    // set up front, before any heavy work, so an eviction still leaves a next
    // alarm armed; (2) a fallback reschedule if either maintenance branch
    // throws. Both only pull the alarm EARLIER or fill a gap; scheduleNextAlarm
    // still refines the exact time (and clears it when truly idle). The floor is
    // gated on someone being online, matching the heartbeat/idle rule, so an
    // empty server still goes idle.
    if (this.humanSocketCount() > 0) {
      try {
        await this.armAlarmBy(Date.now() + houseHeartbeatMs);
      } catch {}
    }
    try {
      await this.houseTick();
    } catch (err) {
      this.houseTickError = err instanceof Error ? err.message : String(err);
      console.error("houseTick failed", err);
    }
    // The full maintenance sweep is the CPU-heavy part (a whole-table scan plus
    // per-match work). Bot moves wake this alarm about once a second; running
    // the sweep every time is what pushed the DO past its CPU limit (#174), so
    // throttle it. On the in-between ticks do only the cheap indexed reschedule
    // so the alarm chain stays alive and live house games keep moving;
    // flag/deadline enforcement and GC still run on the next sweep, at most a
    // few seconds out. Whichever branch runs IS the reschedule point, so if it
    // throws before rescheduling the chain would die — fall back to a short
    // re-arm so the next pass recovers instead of the whole DO going dark.
    // maintenanceAll is now bounded (live-only enforcement off the persisted
    // index + a single bounded GC page), so it is cheap enough to run every
    // alarm and drains any match-table bloat a page at a time. It reschedules
    // via scheduleNextAlarm at its tail; if it throws before that, fall back to
    // a short re-arm so the chain recovers instead of the whole DO going dark.
    try {
      await this.maintenanceAll();
    } catch (err) {
      console.error("maintenanceAll failed", err);
      try {
        await this.armAlarmBy(Date.now() + 2000);
      } catch {}
    }
  }

  // Revive the alarm chain when the stored alarm is missing or well overdue.
  // A chain wedged in the past returns a non-null getAlarm() value, so
  // checking for "missing" alone never recovers a dead roster. Runs on every
  // socket connect and /healthz: getAlarm() is a cheap local read, and a
  // chain can wedge at any point in an isolate's life, so a once-per-isolate
  // latch would leave a later-wedged chain dead until the isolate recycles.
  private async reviveAlarmChain() {
    const existing = await this.ctx.storage.getAlarm();
    if (!existing || existing < Date.now() - houseHeartbeatMs) {
      await this.ctx.storage.setAlarm(Date.now() + 1000);
    }
  }

  private originAllowed(request: Request): boolean {
    const origin = request.headers.get("Origin");
    const configured = (this.env.GAME_SERVER_ORIGINS || "")
      .split(",")
      .map((allowed) => allowed.trim())
      .filter(Boolean);

    // Explicit allowlist: only the configured origins may connect.
    if (configured.length > 0) {
      return !!origin && configured.includes(origin);
    }

    // No allowlist configured: fail closed to same-origin only. Requests
    // without an Origin header (non-browser clients, which cannot be targets
    // of browser CSRF) are still permitted; cross-origin browser requests are
    // rejected instead of being allowed unconditionally.
    if (!origin) return true;
    try {
      return new URL(origin).host === new URL(request.url).host;
    } catch {
      return false;
    }
  }

  private async loadMatch(id: string): Promise<StoredMatch | null> {
    return (await this.ctx.storage.get<StoredMatch>(matchKey(id))) ?? null;
  }

  private async saveMatch(match: StoredMatch, schedule = true) {
    // The match set changed (create / start / move / end), so the cached lobby
    // snapshot is stale. Clearing it forces the next poll to rebuild.
    this.lobbyCache = null;
    await this.ctx.storage.put(matchKey(match.id), match);
    await this.ensureLiveIndex();
    this.trackLive(match);
    await this.persistLiveIndex();
    if (schedule) await this.scheduleAlarmForMatch(match);
  }

  private async deleteMatch(match: StoredMatch) {
    this.lobbyCache = null;
    for (const [ws, session] of this.sessions) {
      if (session.matchId === match.id) {
        this.sessions.delete(ws);
        ws.close(1000, "Game expired");
      }
    }
    this.liveMatchIndex?.delete(match.id);
    await this.ctx.storage.delete(matchKey(match.id));
  }

  // In-memory mirror of the persisted live-match id set (liveIdsKey). The single
  // global DO serializes ALL traffic, so the frequent paths (houseTick,
  // lobbySnapshot) must never deserialize the whole match table just to reach the
  // handful of live games. Kept exact by saveMatch/deleteMatch (which also
  // persist it) and reconciled by the bounded GC sweep.
  private liveMatchIndex: Set<string> | null = null;

  // Cursor into the "match:" keyspace for the bounded GC sweep. Null means the
  // next sweep starts from the beginning of the keyspace.
  private gcCursor: string | null = null;

  // When /healthz last ran its GC sweep. Gates it so an uptime monitor polling
  // /healthz cannot force back-to-back sweeps on the single thread.
  private lastHealthzCleanupAt = 0;

  // Keep the index in step with a write: a finished game leaves the live set,
  // any other save is a live game. Assumes the index is already loaded.
  private trackLive(match: StoredMatch) {
    if (!this.liveMatchIndex) return;
    if (match.result) this.liveMatchIndex.delete(match.id);
    else this.liveMatchIndex.add(match.id);
  }

  // Persist the live-id set so a fresh isolate can load it without a scan.
  private async persistLiveIndex() {
    if (!this.liveMatchIndex) return;
    await this.ctx.storage.put(liveIdsKey, [...this.liveMatchIndex]);
  }

  // Load the live-id set once per isolate from its persisted copy (one cheap
  // get), never from a whole-table scan. The bounded GC sweep folds in any ids
  // the persisted set missed (e.g. a write that raced an isolate restart).
  private async ensureLiveIndex(): Promise<Set<string>> {
    if (this.liveMatchIndex) return this.liveMatchIndex;
    const stored = (await this.ctx.storage.get<string[]>(liveIdsKey)) ?? [];
    this.liveMatchIndex = new Set(stored);
    return this.liveMatchIndex;
  }

  // Load only the unfinished matches, via batched point reads off the live
  // index instead of a full-table scan. A stale entry (record already gone, or
  // finished since the index last updated) is pruned in passing so it stops
  // showing up on the live paths.
  private async loadLiveMatches(): Promise<StoredMatch[]> {
    const index = await this.ensureLiveIndex();
    const ids = [...index];
    const matches: StoredMatch[] = [];
    // storage.get accepts up to 128 keys per batched read.
    for (let i = 0; i < ids.length; i += 128) {
      const chunk = ids.slice(i, i + 128);
      const found = await this.ctx.storage.get<StoredMatch>(chunk.map(matchKey));
      for (const id of chunk) {
        const match = found.get(matchKey(id));
        if (!match || match.result) {
          index.delete(id);
          continue;
        }
        matches.push(match);
      }
    }
    return matches;
  }

  private connectedSession(matchId: string, color: Color): WebSocket | undefined {
    for (const [ws, session] of this.sessions) {
      if (session.matchId === matchId && session.color === color && ws.readyState === WebSocket.OPEN) return ws;
    }
    return undefined;
  }

  private connectedSessions(matchId: string): WebSocket[] {
    return [...this.sessions]
      .filter(([ws, session]) => session.matchId === matchId && ws.readyState === WebSocket.OPEN)
      .map(([ws]) => ws);
  }

  private session(ws: WebSocket): SessionAttachment {
    const restored = ws.deserializeAttachment() as SessionAttachment | null;
    const session = this.sessions.get(ws) ?? restored;
    if (!session) {
      const next = { id: crypto.randomUUID() };
      this.sessions.set(ws, next);
      ws.serializeAttachment(next);
      return next;
    }
    this.sessions.set(ws, session);
    return session;
  }

  private async attachSession(ws: WebSocket, match: StoredMatch, color: Color) {
    const existing = this.connectedSession(match.id, color);
    if (existing && existing !== ws) existing.close(1000, "Reconnected from another tab");

    const session = { ...this.session(ws), matchId: match.id, color, token: match.tokens[color] };
    delete session.watching;
    this.sessions.set(ws, session);
    ws.serializeAttachment(session);
    delete match.disconnectedAt[color];
    delete match.opponentGoneNotified[color];

    // Remember which account holds this seat (used for names in the UI and
    // for game history). Matchmade seats are assigned at pairing and are
    // never overwritten here.
    if (session.userId && session.username && !match.users?.[color]) {
      let rating = 1500;
      let rd = 350;
      let vol = 0.06;
      let avatar: string | null = null;
      const db = await this.db();
      if (db) {
        const row = await this.seatCategoryRating(db, session.userId, this.matchRatingCategory(match));
        if (row) {
          rating = row.rating;
          rd = row.rd;
          vol = row.vol;
          avatar = row.avatar;
        }
      }
      match.users = {
        ...(match.users ?? {}),
        [color]: { id: session.userId, name: session.username, rating, rd, vol, avatar },
      };
    }
  }

  private async detachSession(ws: WebSocket) {
    const session = this.sessions.get(ws) ?? (ws.deserializeAttachment() as SessionAttachment | null);
    this.sessions.delete(ws);
    if (!session?.matchId || !session.color) return;
    if (this.connectedSession(session.matchId, session.color)) return;

    const match = await this.loadMatch(session.matchId);
    if (!match) return;
    match.disconnectedAt[session.color] = Date.now();
    match.opponentGoneNotified[session.color] = false;
    // House game: pause the game clock when the human seat disconnects, so a
    // disconnected human never flags while the bot waits for them (the clock
    // resumes on reconnect). Bank the time run so far first, exactly like a
    // draft-offer pause does. Bots have no socket, so only the human's
    // departure triggers this; the bot itself never "disconnects".
    if (
      match.bots &&
      !match.bots[session.color] &&
      match.startedAt &&
      !match.result &&
      match.runningSince !== null
    ) {
      match.clocks = this.currentClocks(match, Date.now());
      match.runningSince = null;
    }
    await this.saveMatch(match);
  }

  private async newCode(length = 5): Promise<string> {
    let code = randomCode(length);
    while (await this.loadMatch(code)) code = randomCode(length);
    return code;
  }

  private socketForAttachment(id: string): WebSocket | undefined {
    for (const [ws, session] of this.sessions) {
      if (session.id === id && ws.readyState === WebSocket.OPEN) return ws;
    }
    return undefined;
  }

  // Which rating bucket a match plays for: mode games (Draft with a section)
  // use their mode bucket ("nerf"/"buff"); everything else buckets by time
  // control (legacy classic behavior).
  private matchRatingCategory(match: StoredMatch): RatingCategory {
    if (match.draft && match.mode) return match.mode;
    return categoryForTimeControl(match.setup.timeSec, match.setup.incrementSec);
  }

  // Rating shown/staked for a seat, from the independent rating buckets
  // (seeded from the legacy shared rating on first contact).
  private async seatCategoryRating(
    db: D1Database,
    userId: string,
    category: RatingCategory,
  ): Promise<{ rating: number; rd: number; vol: number; avatar: string | null } | null> {
    try {
      const ratings = await loadCategoryRatings(db, [userId], category);
      const r = ratings.get(userId);
      if (!r) return null;
      const row = await db
        .prepare("SELECT avatar FROM users WHERE id = ?")
        .bind(userId)
        .first<{ avatar: string | null }>();
      return { rating: r.rating, rd: r.rd, vol: r.vol, avatar: row?.avatar ?? null };
    } catch {
      return null;
    }
  }

  private playersPayload(match: StoredMatch) {
    const seat = (color: Color) => {
      const user = match.users?.[color];
      return user
        ? { name: user.name, rating: Math.round(user.rating), avatar: user.avatar ?? null }
        : { name: "Anonymous", rating: null, avatar: null };
    };
    return { w: seat("w"), b: seat("b") };
  }

  private sendWatchers(match: StoredMatch, t: string, d?: unknown) {
    for (const [ws, session] of this.sessions) {
      if (session.watching === match.id && ws.readyState === WebSocket.OPEN) send(ws, t, d);
    }
  }

  // Projected rating movement for each seat before the game is decided, so
  // players can see what a win/draw/loss is worth ("+8 / +0 / -8").
  private ratingPreview(match: StoredMatch): Record<Color, { win: number; draw: number; loss: number }> | null {
    if (!match.rated || !match.users?.w || !match.users?.b) return null;
    const w = { rating: match.users.w.rating, rd: match.users.w.rd ?? 350, vol: match.users.w.vol ?? 0.06 };
    const b = { rating: match.users.b.rating, rd: match.users.b.rd ?? 350, vol: match.users.b.vol ?? 0.06 };
    const whiteWins = glickoUpdatePair(w, b, 1);
    const draw = glickoUpdatePair(w, b, 0.5);
    const blackWins = glickoUpdatePair(w, b, 0);
    const delta = (after: number, before: number) => Math.round(after - before);
    return {
      w: {
        win: delta(whiteWins.a.rating, w.rating),
        draw: delta(draw.a.rating, w.rating),
        loss: delta(blackWins.a.rating, w.rating),
      },
      b: {
        win: delta(blackWins.b.rating, b.rating),
        draw: delta(draw.b.rating, b.rating),
        loss: delta(whiteWins.b.rating, b.rating),
      },
    };
  }

  private startPayload(match: StoredMatch, color: Color) {
    const clocks = this.currentClocks(match);
    const myNerfId = color === "w" ? match.setup.whiteNerfId : match.setup.blackNerfId;
    const masterRng = new RNG(match.setup.seed);
    const wSeed = masterRng.fork().getState();
    const bSeed = masterRng.fork().getState();
    const nerfSeed = color === "w" ? wSeed : bSeed;
    const preview = this.ratingPreview(match);
    const revealed: Partial<Record<Color, string>> = {};
    if (match.revealed?.w) revealed.w = match.setup.whiteNerfId;
    if (match.revealed?.b) revealed.b = match.setup.blackNerfId;
    // Draft matches ship the public action record (for exact board replay)
    // plus this seat's filtered view of the live draft state.
    let draftExtras: Record<string, unknown> | null = null;
    if (match.draft) {
      const game = match.startedAt ? this.gameFromMatch(match) : null;
      const opp: Color = color === "w" ? "b" : "w";
      draftExtras = {
        draft: true,
        ...(match.mode ? { mode: match.mode } : {}),
        picksVisible: !!match.picksVisible,
        dtActions: this.publicDraftActions(match, color),
        ...(game?.buffs ? { dtState: this.draftStateFor(game, match, color) } : {}),
        ...(match.dtDeadline ? { dtDeadline: match.dtDeadline } : {}),
        // The opening nerf draft, while unresolved. Both sides' options are
        // public; only this seat's own pick index is included.
        ...(match.nerfOptions && !match.startedAt
          ? {
              nerfDraft: {
                options: match.nerfOptions,
                myPick: match.nerfPicks?.[color] ?? null,
                oppPicked: match.nerfPicks?.[opp] != null,
                deadline: match.nerfDeadline ?? null,
              },
            }
          : {}),
      };
    }
    return {
      id: match.id,
      color,
      token: match.tokens[color],
      nerfId: myNerfId,
      nerfSeed,
      timeSec: match.setup.timeSec,
      incrementSec: match.setup.incrementSec,
      wc: Math.round(clocks.w),
      bc: Math.round(clocks.b),
      moves: match.moves,
      players: this.playersPayload(match),
      rated: !!match.rated,
      chat: match.chat ?? [],
      ...(Object.keys(revealed).length ? { revealed } : {}),
      ...(preview ? { preview } : {}),
      ...(draftExtras ?? {}),
    };
  }

  private sendStart(match: StoredMatch, color: Color) {
    const ws = this.connectedSession(match.id, color);
    send(ws, "start", this.startPayload(match, color));
    if (match.result) {
      const clocks = this.currentClocks(match);
      send(ws, "end", {
        result: match.result,
        wc: Math.round(clocks.w),
        bc: Math.round(clocks.b),
        nerfs: { w: match.setup.whiteNerfId, b: match.setup.blackNerfId },
      });
    }
  }

  private broadcast(match: StoredMatch, t: string, d?: unknown) {
    send(this.connectedSession(match.id, "w"), t, d);
    send(this.connectedSession(match.id, "b"), t, d);
  }

  // Which held-buff instances of the most recently rebuilt draft match are
  // public knowledge, plus which instances each stored pick acquired. Derived
  // fresh on every gameFromMatch replay (never persisted): a buff identity is
  // public once its effect has shown on the table, so the set is a pure
  // function of the action and move record. Rules:
  // - instant cards reveal at pick (their effect lands on the board),
  // - activated cards reveal at use (dtUsed carries the identity so replicas
  //   can apply the effect), along with anything a use appends (Mirror
  //   copies, stolen cards),
  // - passive cards reveal the first time one of their granted moves is
  //   played (the move is tagged with the buff id via `move.via`).
  private draftRebuild: {
    matchId: string;
    revealed: Set<BuffInstance>;
    acquired: Map<number, BuffInstance[]>;
  } | null = null;

  private markBuffRevealed(inst: BuffInstance | undefined) {
    if (inst) this.draftRebuild?.revealed.add(inst);
  }

  private isBuffRevealed(inst: BuffInstance): boolean {
    const def = BUFF_BY_ID[inst.id];
    if (def?.kind === "instant") return true;
    // A passive that filters the opponent's legal moves is felt by the
    // opponent from the moment it is drafted (and its fx motif is meant to
    // paint on their pieces): if their replica does not know the card, the
    // filter never runs there and every filtered move looks legal locally but
    // is rejected by the server: a permanent "board out of sync" experience.
    if (def?.kind === "passive" && def.filterOpponentMoves) return true;
    return this.draftRebuild?.revealed.has(inst) ?? false;
  }

  // A hidden passive whose onMovePlayed hook just mutated the board or added
  // a board effect has shown itself on the table exactly like an instant's
  // pick effect does: mark it revealed so replicas receive its identity and
  // can replay the mutation themselves. Runs after every playMove, both on
  // the live path (commitMove, which also pushes the pre-move state to the
  // replicas) and on every rebuild, so the revealed set is a deterministic
  // function of the move and action record.
  private markHookFiredRevealed(game: NerfGame): void {
    const bs = game.buffs;
    if (!bs?.lastHookMutations) return;
    for (const f of bs.lastHookMutations) {
      this.markBuffRevealed(bs.players[f.color].buffs[f.index]);
    }
  }

  // Live-path companion to markHookFiredRevealed: after playMove, mark the
  // fired hooks revealed and report whether any card was NEWLY revealed. When
  // it was, `pre` (a plain deep clone of the pre-move BuffMatchState) is
  // prepared for the pre-move dtState frame: every clone whose live instance
  // is revealed is marked too, so the frame cannot re-mask cards the replicas
  // already know while it unmasks the one that just fired.
  private revealFiredHooks(game: NerfGame, pre: BuffMatchState): boolean {
    const bs = game.buffs;
    if (!bs?.lastHookMutations) return false;
    let revealedNow = false;
    for (const f of bs.lastHookMutations) {
      const inst = bs.players[f.color].buffs[f.index];
      if (inst && !this.isBuffRevealed(inst)) revealedNow = true;
      this.markBuffRevealed(inst);
    }
    if (!revealedNow) return false;
    for (const color of ["w", "b"] as Color[]) {
      pre.players[color].buffs.forEach((clone, i) => {
        const live = bs.players[color].buffs[i];
        if (live && this.isBuffRevealed(live)) this.markBuffRevealed(clone);
      });
    }
    return true;
  }

  // A move tagged with a held buff's id proves the mover holds that card.
  private markViaRevealed(game: NerfGame, move: Move): boolean {
    if (!move.via || !game.buffs) return false;
    const inst = game.buffs.players[move.color].buffs.find((b) => b.id === move.via);
    if (!inst || this.draftRebuild?.revealed.has(inst)) return false;
    this.markBuffRevealed(inst);
    return true;
  }

  private gameFromMatch(match: StoredMatch): NerfGame | null {
    if (!match.startedAt) return null;
    // Buff mode plays without handicaps: both seats run the unrestricted nerf.
    const nerfById = (id: string) =>
      match.mode === "buff" ? UNRESTRICTED_NERF : PLAYABLE_NERFS.find((nerf) => nerf.id === id);
    const white = nerfById(match.setup.whiteNerfId);
    const black = nerfById(match.setup.blackNerfId);
    if (!white || !black) return null;

    let game = newGame(white, black, match.setup.seed);
    if (match.draft) {
      // Replay under the cadence the game was recorded with (older records
      // carry none and fall back to the mode default).
      enableDraftMode(game, match.draftSeed ?? match.setup.seed, {
        mode: match.mode,
        ...(match.cadence ? { cadence: match.cadence } : {}),
        // Stacked-draft preset: the joining friend (black) drafts +2 tiers on
        // every offer. Re-applied on every rebuild so replays stay identical.
        ...(match.stacked ? { stackFor: "b" as Color, stackBoost: 2 } : {}),
      });
      this.draftRebuild = { matchId: match.id, revealed: new Set(), acquired: new Map() };
    }
    // Draft actions replay interleaved with moves: an action recorded at ply
    // N happened after N accepted moves, so replaying both streams through
    // the engine reproduces the RNG stream, offers, and board mutations
    // exactly. Classic matches carry no actions and take the same path.
    // The match's frozen card-overrides snapshot is installed for the whole
    // replay so offers re-roll from exactly the pools they first rolled from,
    // and cleared in the finally so no other game's rolls ever see it.
    setDraftPoolOverrides(match.draft ? match.cardOverrides ?? null : null);
    try {
      const actions = match.draftActions ?? [];
      let cursor = 0;
      const applyActionsUpTo = (ply: number) => {
        while (cursor < actions.length && actions[cursor].ply <= ply) {
          this.applyStoredDraftAction(game, actions[cursor], cursor);
          cursor += 1;
        }
      };
      for (let i = 0; i < match.moves.length; i++) {
        applyActionsUpTo(i);
        const move = moveByUci(game, match.moves[i]);
        if (!move) return null;
        if (match.draft) this.markViaRevealed(game, move);
        game = playMove(game, move);
        // Re-derive fire-time reveals (hidden passives whose hooks mutated
        // the board on this move) so reconnect payloads unmask them too.
        if (match.draft) this.markHookFiredRevealed(game);
      }
      applyActionsUpTo(match.moves.length);
      if (match.result) game.result = match.result;
      return game;
    } finally {
      setDraftPoolOverrides(null);
    }
  }

  // Rebuild the live game for a play-path caller (moves, resigns, draft
  // frames, house actions). A started, unfinished match whose replay can no
  // longer be trusted is ended gracefully here instead of returning null
  // into a soft-lock: a stamped replayVersion that differs from the current
  // constant means the replay is known-desynced (v2+), and an outright
  // replay failure catches v1 records from before the stamp existed (see
  // REPLAY_VERSION). The draw goes through the normal end flow, so the end
  // frame reaches both seats and the game is recorded, never deleted. The
  // draw is forced UNRATED: a game the server cut short with an update should
  // not move either player's rating (the rating apply path skips unrated, and
  // the end frame reports rated:false to the clients).
  private async gameForPlay(match: StoredMatch): Promise<NerfGame | null> {
    const stale =
      match.replayVersion != null && match.replayVersion !== REPLAY_VERSION && !match.result;
    const game = stale ? null : this.gameFromMatch(match);
    if (!game && match.startedAt && !match.result) {
      match.clocks = this.currentClocks(match);
      match.runningSince = null;
      match.result = { winner: "draw", reason: "server update interrupted this game" };
      match.completedAt = Date.now();
      match.rated = false;
      await this.endMatch(match);
    }
    return game;
  }

  private applyStoredDraftAction(game: NerfGame, action: StoredDraftAction, index: number) {
    if (action.a === "pick") {
      const bs = game.buffs;
      const ps = bs?.players[action.color];
      const before = ps?.buffs.length ?? 0;
      const effectsBefore = bs?.effects.length ?? 0;
      const mutationsBefore = bs?.mutations ?? 0;
      pickDraftCard(game, action.color, action.index);
      const acquired = ps ? ps.buffs.slice(before) : [];
      // A pick whose init observably touched the board or effects is public
      // (mirrors resolveDraftPick): replicas must replay it or they desync.
      if (bs && (bs.effects.length !== effectsBefore || (bs.mutations ?? 0) !== mutationsBefore)) {
        for (const b of acquired) this.markBuffRevealed(b);
      }
      this.draftRebuild?.acquired.set(index, acquired);
    } else if (action.a === "bank") {
      bankDraft(game, action.color);
    } else {
      const bs = game.buffs;
      const mine = bs?.players[action.color];
      const theirs = bs?.players[action.color === "w" ? "b" : "w"];
      const inst = mine?.buffs[action.buffIndex];
      const mineBefore = mine?.buffs.length ?? 0;
      const theirsBefore = theirs?.buffs.length ?? 0;
      activateBuff(game, action.color, action.buffIndex, action.picks);
      // Using a card makes it public, along with anything the use created or
      // moved between the players (Mirror copies, stolen cards).
      this.markBuffRevealed(inst);
      for (const added of mine?.buffs.slice(mineBefore) ?? []) this.markBuffRevealed(added);
      for (const added of theirs?.buffs.slice(theirsBefore) ?? []) this.markBuffRevealed(added);
    }
  }

  // Moves the given color has already played (moves alternate w, b, w, …).
  private movesByColor(match: StoredMatch, color: Color): number {
    return color === "w" ? Math.ceil(match.moves.length / 2) : Math.floor(match.moves.length / 2);
  }

  // Whose turn it is. Classic turns always alternate w, b, w, … so this is
  // pure move-count parity, with no need to replay the game. Keeping clock
  // and flag checks off the replay path is what stops the single-threaded
  // Durable Object from stalling live sockets and the lobby. Draft games
  // track the real turn on the match instead (buff activations and tempo
  // cards move it off parity).
  private activeColor(match: StoredMatch): Color {
    return match.turnColor ?? (match.moves.length % 2 === 0 ? "w" : "b");
  }

  private currentClocks(match: StoredMatch, now = Date.now()): Record<Color, number> {
    const clocks = { ...match.clocks };
    if (!match.setup.timeSec || match.result || !match.startedAt || match.runningSince === null) return clocks;
    const active = this.activeColor(match);
    let elapsed = now - match.runningSince;
    // Start-of-game grace: the first move of each side gets 10 free seconds.
    if (this.movesByColor(match, active) === 0) {
      elapsed = Math.max(0, elapsed - firstMoveGraceMs);
    }
    clocks[active] = Math.max(0, clocks[active] - elapsed);
    return clocks;
  }

  private async finishOnFlag(match: StoredMatch, now = Date.now(), schedule = true): Promise<boolean> {
    if (!match.startedAt || match.result || !match.setup.timeSec) return false;
    const clocks = this.currentClocks(match, now);
    const active = this.activeColor(match);
    if (clocks[active] > 0) return false;

    match.clocks = clocks;
    match.runningSince = null;
    match.result = {
      winner: active === "w" ? "b" : "w",
      reason: active === "w" ? "white ran out of time" : "black ran out of time",
    };
    match.completedAt = now;
    await this.endMatch(match, schedule);
    return true;
  }

  // Final-board facts for achievement evaluation: material per side (kings
  // excluded) and the highest-tier card each side drafted. Computed from the
  // replayed end state, best-effort: a replay hiccup just yields nothing, which
  // only means the material/draft achievements do not fire for this game.
  private achievementExtras(match: StoredMatch): AchievementExtras {
    try {
      const game = match.startedAt ? this.gameFromMatch(match) : null;
      if (!game) return {};
      const material: Record<Color, number> = { w: 0, b: 0 };
      for (const piece of game.board.pieces) {
        if (piece && piece.type !== "k") material[piece.color] += PIECE_VALUE[piece.type];
      }
      const maxBuffTier: Record<Color, number> = { w: 0, b: 0 };
      if (game.buffs) {
        for (const color of ["w", "b"] as Color[]) {
          for (const b of game.buffs.players[color].buffs) {
            const tier = b.tier as number;
            if (tier > maxBuffTier[color]) maxBuffTier[color] = tier;
          }
        }
      }
      return { material, maxBuffTier };
    } catch {
      return {};
    }
  }

  // Single exit point for a finished match: persist it to D1 (updating both
  // ratings when the game was rated), then notify players and spectators.
  private async endMatch(match: StoredMatch, schedule = true) {
    if (!match.result) return;
    if (!match.completedAt) match.completedAt = Date.now();

    let ratings: { w: RatingChange | null; b: RatingChange | null } | null = null;
    if (!match.recorded && match.startedAt) {
      match.recorded = true;
      const db = await this.db();
      if (db) {
        try {
          const recorded = await recordFinishedGame(db, {
            id: match.id,
            whiteUserId: match.users?.w?.id ?? null,
            blackUserId: match.users?.b?.id ?? null,
            whiteName: match.users?.w?.name ?? "Anonymous",
            blackName: match.users?.b?.name ?? "Anonymous",
            whiteNerfId: match.setup.whiteNerfId,
            blackNerfId: match.setup.blackNerfId,
            seed: match.setup.seed,
            timeSec: match.setup.timeSec,
            incrementSec: match.setup.incrementSec,
            moves: match.moves,
            winner: match.result.winner,
            reason: match.result.reason,
            rated: !!match.rated,
            ...(match.draft ? { ruleset: "draft" } : {}),
            // Mode games count toward (and, when rated, move) the per-mode
            // rating bucket instead of a speed bucket.
            ...(match.draft && match.mode ? { ratingCategory: match.mode } : {}),
            startedAt: match.startedAt,
            completedAt: match.completedAt,
          }, this.env.HYPERDRIVE?.connectionString, this.achievementExtras(match));
          if (recorded.white || recorded.black) {
            ratings = { w: recorded.white, b: recorded.black };
          }
        } catch (err) {
          console.error("failed to record game", match.id, err);
        }
      }
    }
    await this.saveMatch(match, schedule);

    const clocks = this.currentClocks(match);
    // Draft games also close with the public draft record: each side's held
    // buffs (public all game anyway, repeated here for post-game screens).
    let draftBuffs: Record<Color, { id: string; tier: number; spent?: boolean; nullified?: boolean }[]> | null = null;
    if (match.draft) {
      try {
        const game = this.gameFromMatch(match);
        if (game?.buffs) {
          const held = (color: Color) =>
            game.buffs!.players[color].buffs.map((b) => ({
              id: b.id,
              tier: b.tier as number,
              ...(b.spent ? { spent: true } : {}),
              ...(b.nullified ? { nullified: true } : {}),
            }));
          draftBuffs = { w: held("w"), b: held("b") };
        }
      } catch {
        // The end frame must go out even if the draft replay hiccups.
      }
    }
    // Both secret rules become public at game end — players and spectators
    // all receive them with the result.
    const payload = {
      result: match.result,
      wc: Math.round(clocks.w),
      bc: Math.round(clocks.b),
      nerfs: { w: match.setup.whiteNerfId, b: match.setup.blackNerfId },
      ...(ratings ? { ratings } : {}),
      ...(draftBuffs ? { draftBuffs } : {}),
    };
    this.broadcast(match, "end", payload);
    this.sendWatchers(match, "end", payload);
  }

  private async createMatch(ws: WebSocket, data: unknown) {
    const session = this.session(ws);
    if (session.matchId) return error(ws, "already_joined", "This connection already belongs to a game.");

    const requested = (data || {}) as { timeSec?: unknown; incrementSec?: unknown; draft?: unknown; mode?: unknown; picksVisible?: unknown; invite?: unknown; stacked?: unknown; rated?: unknown };
    const timeSec = Number.isInteger(requested.timeSec) ? Number(requested.timeSec) : 600;
    const incrementSec = Number.isInteger(requested.incrementSec) ? Number(requested.incrementSec) : 0;
    if (timeSec < 0 || timeSec > 7200 || incrementSec < 0 || incrementSec > 60) {
      return error(ws, "invalid_clock", "Unsupported time control.");
    }
    // Custom challenges may opt into a rated game. Rating still only moves when
    // both seats belong to accounts (attachSession fills match.users for signed
    // -in seats, and recordFinishedGame no-ops the rating when either side is
    // anonymous), so a rated flag on an anonymous game degrades to casual on
    // its own. The category is the same bucket the queue uses (mode for Draft,
    // else time control), so a rated custom game moves the normal rating.
    const rated = requested.rated === true;
    // Optional Draft ruleset for friend games.
    const draft = requested.draft === true;
    // The game's section: "nerf" or "buff". Older clients send neither and
    // get the legacy merged rules.
    const mode: DraftMode | undefined =
      draft && (requested.mode === "nerf" || requested.mode === "buff") ? requested.mode : undefined;
    const picksVisible = draft && requested.picksVisible === true;
    // "Surprise / Stacked draft" preset: the joining friend drafts strong,
    // high-tier cards. Casual only, and only meaningful in a draft game.
    const stacked = draft && requested.stacked === true;
    // Direct challenge: reserve the black seat for the named player. Only a
    // signed-in host can address a challenge (the API notification requires
    // an account anyway).
    const invite =
      session.userId && typeof requested.invite === "string" ? requested.invite.trim().slice(0, 30) : "";

    const id = await this.newCode();
    // Moderator card overrides: disabled nerfs leave the dealt pair, and the
    // draft-pool slice is frozen onto the match record (see cardOverrides).
    const cardSnap = await this.cardOverridesSnapshot();
    const cardOverrides = draft ? this.draftPoolStamp(cardSnap) : undefined;
    const match: StoredMatch = {
      id,
      setup: {
        // Buff mode has no handicaps: both seats carry the unrestricted
        // "none" rule instead of dealt nerfs.
        ...(mode === "buff"
          ? { whiteNerfId: UNRESTRICTED_NERF.id, blackNerfId: UNRESTRICTED_NERF.id }
          : pickNerfIds(cardSnap.nerfOff)),
        seed: makeSeed(),
        timeSec,
        incrementSec,
      },
      tokens: { w: newToken(), b: newToken() },
      disconnectedAt: {},
      opponentGoneNotified: {},
      moves: [],
      result: null,
      clocks: { w: timeSec * 1000, b: timeSec * 1000 },
      runningSince: null,
      drawOfferBy: null,
      createdAt: Date.now(),
      startedAt: null,
      completedAt: null,
      replayVersion: REPLAY_VERSION,
      ...(rated ? { rated: true } : {}),
      ...(draft
        ? {
            draft: true,
            ...(mode ? { mode } : {}),
            picksVisible,
            ...(stacked ? { stacked: true } : {}),
            cadence: mode === "nerf" ? NERF_MODE_CADENCE : DEFAULT_CADENCE,
            draftSeed: makeSeed(),
            ...(cardOverrides ? { cardOverrides } : {}),
            draftActions: [],
          }
        : {}),
      ...(invite ? { invitedUsername: invite } : {}),
    };

    await this.attachSession(ws, match, "w");
    await this.saveMatch(match);
    send(ws, "created", { id, color: "w", token: match.tokens.w });
  }

  private async joinMatch(ws: WebSocket, data: unknown) {
    const session = this.session(ws);
    if (session.matchId) return error(ws, "already_joined", "This connection already belongs to a game.");

    const id = String((data as { id?: unknown } | undefined)?.id || "").trim().toUpperCase();
    const match = await this.loadMatch(id);
    // A dealt nerf draft means both seats are claimed even though the game
    // has not started, so the code is no longer joinable.
    if (!match || match.startedAt || match.nerfOptions || this.connectedSession(id, "b")) {
      return error(ws, "not_found", "That code is not accepting a player.");
    }
    // Direct challenges are reserved: only the invited account may take the
    // black seat, so a lobby stranger can never race the invitee to it.
    if (
      match.invitedUsername &&
      match.invitedUsername.toLowerCase() !== (session.username ?? "").toLowerCase()
    ) {
      return error(ws, "invite_only", "This game is reserved for the invited player.");
    }
    // The host is gone (navigated away or closed the tab): joining would
    // start a game against an empty seat. Tell the joiner plainly instead.
    if (!this.connectedSession(id, "w")) {
      return error(ws, "host_gone", "The player who created this game has left.");
    }

    await this.attachSession(ws, match, "b");
    // Draft games open with the nerf draft instead of starting outright.
    // Buff mode has no nerfs, so it starts like a classic game.
    if (match.draft && match.mode !== "buff") return this.beginNerfDraft(match);
    match.startedAt = Date.now();
    match.runningSince = match.startedAt;
    await this.saveMatch(match);
    this.sendStart(match, "w");
    this.sendStart(match, "b");
  }

  private async reconnectMatch(ws: WebSocket, data: unknown) {
    const session = this.session(ws);
    if (session.matchId) return error(ws, "already_joined", "This connection already belongs to a game.");

    const request = (data || {}) as { id?: unknown; color?: unknown; token?: unknown };
    const id = String(request.id || "").trim().toUpperCase();
    const color = isColor(request.color) ? request.color : null;
    const token = typeof request.token === "string" ? request.token : "";
    const match = await this.loadMatch(id);
    if (!match || !color || match.tokens[color] !== token) {
      return error(ws, "reconnect_failed", "Could not resume that game.");
    }

    await this.attachSession(ws, match, color);
    await this.saveMatch(match);
    if (!match.startedAt) {
      // Mid nerf draft: resume it. The start payload restores this seat's
      // options and pick state (a seat that already picked sees the waiting
      // state again).
      if (match.nerfOptions) return this.sendStart(match, color);
      // Matchmade and rematch games begin the moment both paired players
      // arrive at the game URL; friend games wait in the lobby for a join.
      // A house-player seat counts as arrived (it has no socket).
      if ((match.rated || match.autoStart) && this.seatReady(match, "w") && this.seatReady(match, "b")) {
        // Buff mode skips the opening nerf draft entirely.
        if (match.draft && match.mode !== "buff") return this.beginNerfDraft(match);
        match.startedAt = Date.now();
        match.runningSince = match.startedAt;
        this.armBotAction(match, null, match.startedAt);
        await this.saveMatch(match);
        this.sendStart(match, "w");
        this.sendStart(match, "b");
        return;
      }
      return send(ws, "created", { id, color, token: match.tokens[color] });
    }
    // A live draft game whose replay went stale across a deploy ends now,
    // through gameForPlay's graceful draw, so the returning player gets the
    // end frame instead of a board that can never accept a move.
    if (match.draft && !match.result) await this.gameForPlay(match);
    // House game: the clock was paused when this human seat disconnected;
    // resume it now that they are back, unless a draft offer's lock-in window
    // is still holding it paused. Re-arm the bot so it resumes acting on its
    // turn (its timer may have been left armed while play was paused).
    if (
      match.bots &&
      !match.bots[color] &&
      match.startedAt &&
      !match.result &&
      match.runningSince === null
    ) {
      const offerHolding = !!match.dtDeadline && Date.now() < match.dtDeadline;
      if (!offerHolding) {
        match.runningSince = Date.now();
        this.armBotAction(match, null, Date.now());
        await this.saveMatch(match);
      }
    }
    this.sendStart(match, color);
    // A rematch was created while this seat was away (page refresh or dropped
    // socket mid-rematch): re-deliver the seat in the new game so the player
    // reclaims it instead of arriving at the rematch as a spectator. Only
    // while the rematch is still unfinished, so revisiting an old game page
    // never bounces into an already-decided one.
    if (match.rematchedTo) {
      const rematch = await this.loadMatch(match.rematchedTo);
      if (rematch && !rematch.result) {
        const newColor: Color = color === "w" ? "b" : "w";
        send(ws, "rematched", { id: rematch.id, color: newColor, token: rematch.tokens[newColor] });
      }
    }
  }

  private async playClientMove(ws: WebSocket, data: unknown) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before sending moves.");
    if (await this.finishOnFlag(match)) return;
    if (match.result) return error(ws, "game_over", "This game is over.");
    // Draft games: no moves while the opening nerf draft is unresolved.
    if (match.draft && match.nerfOptions && !match.startedAt) {
      return error(ws, "nerf_pending", "Pick your nerf before the game starts.");
    }

    const game = await this.gameForPlay(match);
    // gameForPlay already ended a match whose replay went stale (the end
    // frame is on its way to this seat); only a genuinely unjoined game
    // still warrants the error.
    if (!game) return match.result ? undefined : error(ws, "no_game", "Join a game before sending moves.");
    if (game.board.turn !== session.color) return error(ws, "not_your_turn", "It is not your turn.");
    // Draft games: a pending buff offer blocks the seat's moves, mirroring
    // how the client blocks the board until the draft is resolved.
    if (match.draft && game.buffs?.players[session.color].offer) {
      return error(ws, "draft_pending", "Resolve your buff draft before moving.");
    }

    const request = (data || {}) as { u?: unknown; ply?: unknown };
    const uci = typeof request.u === "string" ? request.u.toLowerCase() : "";
    if (Number.isInteger(request.ply) && Number(request.ply) !== match.moves.length) {
      return error(ws, "stale_ply", "Your board is out of date.");
    }
    const move = moveByUci(game, uci);
    if (!move) return error(ws, "illegal_move", "That move is not legal in the current position.");

    await this.commitMove(match, game, session.color, move, uci);
  }

  // Apply an accepted move and everything that follows it: clocks, pending
  // offer declines, draft offer rolls and deadlines, broadcasts, and the end
  // flow. Shared verbatim by human moves (playClientMove) and house-player
  // moves (playHouseAction), so a house game's record and wire frames are
  // identical to a human game's.
  private async commitMove(match: StoredMatch, game: NerfGame, mover: Color, move: Move, uci: string) {
    const now = Date.now();
    match.clocks = this.currentClocks(match, now);
    if (match.drawOfferBy && match.drawOfferBy !== mover) {
      match.drawOfferBy = null;
      this.broadcast(match, "drawDeclined", { color: mover });
    }
    // Moving past an opponent's takeback request declines it.
    if (match.takebackOfferBy && match.takebackOfferBy !== mover) {
      match.takebackOfferBy = null;
      this.broadcast(match, "takebackDeclined", { color: mover });
    }
    // Which seats already had a pending offer: playMove mutates the game, so
    // newly rolled offers are detected against this pre-move snapshot.
    const offersBefore =
      match.draft && game.buffs
        ? { w: !!game.buffs.players.w.offer, b: !!game.buffs.players.b.offer }
        : null;
    // A move granted by a hidden passive buff proves the mover holds that
    // card: reveal it to the table BEFORE the move goes out, so replicas can
    // regenerate the granted move when they replay the frame. The dtState is
    // computed on the pre-move game so replicas tick charges exactly once.
    if (match.draft && game.buffs && !match.picksVisible && this.markViaRevealed(game, move)) {
      this.sendDraftState(match, game);
      this.sendWatcherDraftState(match, game);
    }
    // Snapshot the pre-move draft state (plain serializable data). If a
    // hidden passive's hook fires inside playMove (a capture detonation, a
    // triggered summon...), its identity plus PRE-move card state must reach
    // every replica BEFORE the move frame, so the replica's own playMove
    // replays the same board mutation. dtState never carries the board, so a
    // hook a replica skips is a permanent desync; this is the onMovePlayed
    // analogue of the via-reveal above.
    const preBuffs: BuffMatchState | null =
      match.draft && game.buffs ? (JSON.parse(JSON.stringify(game.buffs)) as BuffMatchState) : null;
    // Live moves roll offers under the same frozen overrides snapshot the
    // rebuild path uses; cleared right after so nothing else inherits it.
    setDraftPoolOverrides(match.draft ? match.cardOverrides ?? null : null);
    let nextGame: NerfGame;
    try {
      nextGame = playMove(game, move);
    } finally {
      setDraftPoolOverrides(null);
    }
    if (preBuffs && this.revealFiredHooks(nextGame, preBuffs)) {
      const preGame = { buffs: preBuffs } as unknown as NerfGame;
      this.sendDraftState(match, preGame);
      this.sendWatcherDraftState(match, preGame);
    }
    match.moves.push(uci);
    // Draft games: extra moves and skips can leave the turn off parity.
    if (match.draft) match.turnColor = nextGame.board.turn;
    if (match.setup.timeSec) match.clocks[mover] += match.setup.incrementSec * 1000;
    const offersPending =
      match.draft && nextGame.buffs
        ? !!nextGame.buffs.players.w.offer || !!nextGame.buffs.players.b.offer
        : false;
    const rolledNow = ["w", "b"].some(
      (color) => nextGame.buffs?.players[color as Color].offer && !offersBefore?.[color as Color],
    );
    if (match.draft) {
      if (rolledNow && !nextGame.result) match.dtDeadline = now + draftLockInMs;
      else if (!offersPending) match.dtDeadline = null;
    }
    // A pending buff offer pauses the game clock only during its free
    // lock-in window (dtDeadline). Once the window has expired the clock
    // runs on: deliberating past it costs the straggler's own time.
    match.runningSince = nextGame.result || (offersPending && match.dtDeadline) ? null : now;
    match.result = nextGame.result;
    if (nextGame.result) match.completedAt = now;
    // House seats: arm the next pending house action (a reply move, or a
    // freshly rolled offer on the house side). No-op for purely human games.
    this.armBotAction(match, nextGame, now);
    await this.saveMatch(match);

    const movePayload = {
      u: uci,
      ply: match.moves.length,
      wc: Math.round(match.clocks.w),
      bc: Math.round(match.clocks.b),
      // Desync telemetry: hash of the authoritative post-move position
      // (placement, turn, castling, ep). A replica that applies this move and
      // lands on a different hash has silently diverged and should resync +
      // beacon (see src/engine/desync.ts and /api/desync).
      f: fnv1a(positionKey(nextGame.board)),
    };
    this.broadcast(match, "move", movePayload);
    this.sendWatchers(match, "move", movePayload);
    if (match.draft && nextGame.buffs) {
      // The shared draft cadence rolls offers for BOTH seats on the same
      // move, so each seat whose offer appeared gets its dtOffer frame now,
      // not just the mover's. dtOffer goes to the drafting seat only, plus
      // the opponent when the match was created with visible picks.
      // Spectators never see offers.
      let rolledAny = false;
      for (const color of ["w", "b"] as Color[]) {
        const rolled = nextGame.buffs.players[color].offer;
        if (!rolled || offersBefore?.[color]) continue;
        rolledAny = true;
        const offerPayload = {
          color,
          cards: rolled.cards,
          index: rolled.index,
          ...(rolled.banked ? { banked: true } : {}),
          ...(match.dtDeadline ? { deadline: match.dtDeadline } : {}),
        };
        send(this.connectedSession(match.id, color), "dtOffer", offerPayload);
        if (match.picksVisible) {
          send(this.connectedSession(match.id, color === "w" ? "b" : "w"), "dtOffer", offerPayload);
        }
      }
      if (rolledAny) this.sendDraftState(match, nextGame);
    }
    if (match.result) await this.endMatch(match);
  }

  private async resignGame(ws: WebSocket) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before resigning.");
    if (await this.finishOnFlag(match)) return;
    if (match.result) return;

    const game = await this.gameForPlay(match);
    if (!game) return match.result ? undefined : error(ws, "no_game", "Join a game before resigning.");

    match.clocks = this.currentClocks(match);
    match.runningSince = null;
    match.result = resign(game, session.color).result;
    match.completedAt = Date.now();
    await this.endMatch(match);
  }

  // ---------------- abandonment claims ----------------

  // Once the opponent has been disconnected for 30+ seconds in a started,
  // unfinished game, the remaining player may end it as a win or a draw.
  private async claimAbandonment(ws: WebSocket, draw: boolean) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before claiming.");
    if (await this.finishOnFlag(match)) return;
    if (match.result) return;
    if (!match.startedAt) return error(ws, "not_started", "The game has not started yet.");

    const opponent: Color = session.color === "w" ? "b" : "w";
    const disconnectedAt = match.disconnectedAt[opponent];
    if (
      this.connectedSession(match.id, opponent) ||
      !disconnectedAt ||
      Date.now() - disconnectedAt < abandonmentClaimMs
    ) {
      return error(ws, "no_claim", "Your opponent has not been gone long enough to claim.");
    }

    match.clocks = this.currentClocks(match);
    match.runningSince = null;
    match.result = draw
      ? { winner: "draw", reason: "abandonment" }
      : { winner: session.color, reason: "abandonment" };
    match.completedAt = Date.now();
    await this.endMatch(match);
  }

  private async offerDraw(ws: WebSocket) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before offering a draw.");
    if (await this.finishOnFlag(match)) return;
    if (match.result) return;
    if (match.drawOfferBy === session.color) return error(ws, "draw_pending", "Your draw offer is already pending.");
    if (match.drawOfferBy && match.drawOfferBy !== session.color) return this.acceptDraw(ws);

    match.drawOfferBy = session.color;
    await this.saveMatch(match);
    this.broadcast(match, "drawOffer", { color: session.color });
  }

  private async acceptDraw(ws: WebSocket) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before accepting a draw.");
    if (await this.finishOnFlag(match)) return;
    if (match.result) return;
    if (!match.drawOfferBy || match.drawOfferBy === session.color) {
      return error(ws, "no_draw_offer", "There is no opponent draw offer to accept.");
    }

    match.clocks = this.currentClocks(match);
    match.runningSince = null;
    match.drawOfferBy = null;
    match.result = { winner: "draw", reason: "draw by agreement" };
    match.completedAt = Date.now();
    await this.endMatch(match);
  }

  private async declineDraw(ws: WebSocket) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before declining a draw.");
    if (await this.finishOnFlag(match)) return;
    if (match.result) return;
    if (!match.drawOfferBy || match.drawOfferBy === session.color) {
      return error(ws, "no_draw_offer", "There is no opponent draw offer to decline.");
    }

    match.drawOfferBy = null;
    await this.saveMatch(match);
    this.broadcast(match, "drawDeclined", { color: session.color });
  }

  // ---------------- takebacks (casual games only) ----------------

  // How many plies an accepted takeback removes: the offerer's last move,
  // plus the opponent's reply if they already answered it.
  private takebackPlies(match: StoredMatch, offerer: Color): number {
    const lastMover: Color = match.moves.length % 2 === 1 ? "w" : "b";
    return lastMover === offerer ? 1 : 2;
  }

  private async offerTakeback(ws: WebSocket) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before requesting a takeback.");
    if (await this.finishOnFlag(match)) return;
    if (match.result) return;
    if (match.rated) return error(ws, "takeback_rated", "Takebacks are not allowed in rated games.");
    // Draft state (rolled offers, consumed RNG, applied buffs) cannot be
    // rewound, so draft games have no takebacks.
    if (match.draft) return error(ws, "takeback_draft", "Takebacks are not available in Draft games.");
    const myMoves = session.color === "w" ? Math.ceil(match.moves.length / 2) : Math.floor(match.moves.length / 2);
    if (myMoves === 0) return error(ws, "no_moves", "You have no move to take back.");
    if (this.takebackPlies(match, session.color) > match.moves.length) {
      return error(ws, "no_moves", "You have no move to take back.");
    }
    if (match.takebackOfferBy === session.color) {
      return error(ws, "takeback_pending", "Your takeback request is already pending.");
    }
    if (match.takebackOfferBy && match.takebackOfferBy !== session.color) return this.acceptTakeback(ws);

    match.takebackOfferBy = session.color;
    await this.saveMatch(match);
    this.broadcast(match, "takebackOffer", { color: session.color });
  }

  private async acceptTakeback(ws: WebSocket) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before accepting a takeback.");
    if (await this.finishOnFlag(match)) return;
    if (match.result) return;
    const offerer = match.takebackOfferBy;
    if (!offerer || offerer === session.color) {
      return error(ws, "no_takeback_offer", "There is no takeback request to accept.");
    }

    const remove = this.takebackPlies(match, offerer);
    if (remove > match.moves.length) {
      match.takebackOfferBy = null;
      await this.saveMatch(match);
      return error(ws, "no_moves", "There is nothing to take back.");
    }

    const now = Date.now();
    match.clocks = this.currentClocks(match, now);
    match.moves = match.moves.slice(0, match.moves.length - remove);
    match.takebackOfferBy = null;
    match.runningSince = match.startedAt ? now : null;
    await this.saveMatch(match);

    const payload = {
      by: offerer,
      moves: match.moves,
      ply: match.moves.length,
      wc: Math.round(match.clocks.w),
      bc: Math.round(match.clocks.b),
    };
    this.broadcast(match, "takeback", payload);
    this.sendWatchers(match, "takeback", payload);
  }

  private async declineTakeback(ws: WebSocket) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before declining a takeback.");
    if (await this.finishOnFlag(match)) return;
    if (match.result) return;
    if (!match.takebackOfferBy || match.takebackOfferBy === session.color) {
      return error(ws, "no_takeback_offer", "There is no takeback request to decline.");
    }

    match.takebackOfferBy = null;
    await this.saveMatch(match);
    this.broadcast(match, "takebackDeclined", { color: session.color });
  }

  // ---------------- matchmaking queue ----------------

  private queueKey(mode: DraftMode, pool: string): string {
    return `queue:${mode}:${pool}`;
  }

  private async queueJoin(ws: WebSocket, data: unknown) {
    const session = this.session(ws);
    if (session.matchId) return error(ws, "already_joined", "This connection already belongs to a game.");
    if (!session.userId || !session.username) {
      return error(ws, "auth_required", "Sign in to use quick pairing.");
    }
    const req = (data as { pool?: unknown; mode?: unknown; target?: unknown } | undefined) ?? {};
    const poolName = String(req.pool || "3+2");
    const pool = QUEUE_POOLS[poolName];
    if (!pool) return error(ws, "bad_pool", "Unknown queue pool.");
    // Which of the two pools (Nerf or Buff) this seek enters. Older clients
    // send no mode and land in Buff, which is what the queue always ran.
    const mode: DraftMode = req.mode === "nerf" ? "nerf" : "buff";
    // Answering a specific lobby seek carries that seeker's identity. A targeted
    // join must pair ONLY with that person (or that house persona) — never a
    // random pool waiter or a random bot. Untargeted frames (the main Quick
    // Pair button) leave this null and keep pairing with whoever is first.
    const targetUserId =
      typeof (req.target as { userId?: unknown } | undefined)?.userId === "string"
        ? String((req.target as { userId: string }).userId).slice(0, 64)
        : "";
    const db = await this.db();
    if (!db) return error(ws, "server_unconfigured", "Matchmaking is unavailable right now.");

    let rating = 1500;
    let rd = 350;
    let vol = 0.06;
    let avatar: string | null = null;
    {
      // Queueing reads (and stakes) the rating bucket for this pool's mode,
      // shown beside names and updated when the game ends: queue games are
      // rated under the per-mode buckets.
      const row = await this.seatCategoryRating(db, session.userId, mode);
      if (row) {
        rating = row.rating;
        rd = row.rd;
        vol = row.vol;
        avatar = row.avatar;
      }
    }

    const key = this.queueKey(mode, poolName);
    let entries = (await this.ctx.storage.get<QueueEntry[]>(key)) ?? [];
    // Drop dead sockets and any previous entry by this same account.
    entries = entries.filter(
      (entry) => entry.userId !== session.userId && this.socketForAttachment(entry.attachmentId),
    );

    const me: SeatUser = { id: session.userId, name: session.username, rating, rd, vol, avatar };

    // Targeted join: the player tapped a specific seek row in the lobby, so
    // they mean to play THAT person. Pair only with them; a stale seek must
    // report "no longer waiting" rather than fall through to a random pool
    // waiter or (via the house pickup) a random bot.
    if (targetUserId) {
      if (targetUserId === session.userId) {
        return error(ws, "seek_gone", "That player is no longer waiting.");
      }
      // A house-persona seek pairs immediately with that exact bot. A human
      // explicitly asked for THIS game, so honour it past the background cap.
      if (isHouseUserId(targetUserId)) {
        // House players are paused: their seeks are cleared, but a stale client
        // may still try to accept one. Treat it as gone.
        if (!(await this.houseEnabled())) return error(ws, "seek_gone", "That player is no longer waiting.");
        const persona = housePersona(targetUserId);
        if (!persona) return error(ws, "seek_gone", "That player is no longer waiting.");
        const meEntry: QueueEntry = {
          attachmentId: session.id,
          userId: session.userId,
          username: session.username,
          rating,
          rd,
          vol,
          avatar,
          at: Date.now(),
        };
        await this.pairHumanWithHouse(meEntry, ws, poolName, mode, persona, db);
        // Retire that persona's advertised seek so it stops showing as waiting.
        try {
          const seeks = (await this.ctx.storage.get<HouseSeekEntry[]>(houseSeeksKey)) ?? [];
          const remaining = seeks.filter((seek) => seek.userId !== persona.userId);
          if (remaining.length !== seeks.length) await this.ctx.storage.put(houseSeeksKey, remaining);
        } catch {}
        return;
      }
      // A human seek: match by account id (never by name or `at`, so a re-queue
      // is still the same person) and only if their socket is still live.
      const idx = entries.findIndex(
        (entry) => entry.userId === targetUserId && this.socketForAttachment(entry.attachmentId),
      );
      if (idx < 0) return error(ws, "seek_gone", "That player is no longer waiting.");
      const opponent = entries.splice(idx, 1)[0];
      await this.ctx.storage.put(key, entries);
      return this.createQueueMatch(ws, me, opponent, poolName, mode);
    }

    const opponent = entries.shift();
    if (!opponent) {
      entries.push({
        attachmentId: session.id,
        userId: session.userId,
        username: session.username,
        rating,
        rd,
        vol,
        avatar,
        at: Date.now(),
      });
      await this.ctx.storage.put(key, entries);
      // Nobody was waiting: make sure the alarm fires soon so a house player
      // can pick this seek up if no human arrives (houseTick pairs a lone
      // human with a persona after ~4.5s; a human opponent queueing in the
      // meantime still pairs instantly through this method).
      try {
        await this.armAlarmBy(Date.now() + houseHumanPickupMs);
      } catch {}
      return send(ws, "queued", { pool: poolName, mode });
    }
    await this.ctx.storage.put(key, entries);
    return this.createQueueMatch(ws, me, opponent, poolName, mode);
  }

  // Create and store a rated queue match between the caller (already seated as
  // `me`) and a waiting `opponent`, then send both the `paired` frame. Shared
  // verbatim by quick pairing (pair-with-anyone) and a targeted seek join, so
  // both produce identical rated games.
  private async createQueueMatch(
    ws: WebSocket,
    me: SeatUser,
    opponent: QueueEntry,
    poolName: string,
    mode: DraftMode,
  ) {
    const pool = QUEUE_POOLS[poolName];
    const opponentWs = this.socketForAttachment(opponent.attachmentId)!;
    const meWhite = randomInt(2) === 0;
    const them: SeatUser = {
      id: opponent.userId,
      name: opponent.username,
      rating: opponent.rating,
      rd: opponent.rd,
      vol: opponent.vol,
      avatar: opponent.avatar ?? null,
    };
    const id = await this.newCode(8);
    const cardSnap = await this.cardOverridesSnapshot();
    const cardOverrides = this.draftPoolStamp(cardSnap);
    const match: StoredMatch = {
      id,
      setup: {
        // Buff mode has no nerfs, so no dealt rules either. Nerf mode deals
        // an initial pair the same way friend games do; the opening nerf
        // draft replaces both ids once the players pick.
        ...(mode === "buff"
          ? { whiteNerfId: UNRESTRICTED_NERF.id, blackNerfId: UNRESTRICTED_NERF.id }
          : pickNerfIds(cardSnap.nerfOff)),
        seed: makeSeed(),
        timeSec: pool.timeSec,
        incrementSec: pool.incrementSec,
      },
      tokens: { w: newToken(), b: newToken() },
      disconnectedAt: {},
      opponentGoneNotified: {},
      moves: [],
      result: null,
      clocks: { w: pool.timeSec * 1000, b: pool.timeSec * 1000 },
      runningSince: null,
      drawOfferBy: null,
      createdAt: Date.now(),
      startedAt: null,
      completedAt: null,
      // Queue games are rated under the pool's mode bucket ("nerf"/"buff").
      // Friend and challenge games never set `rated`, so they stay casual.
      replayVersion: REPLAY_VERSION,
      rated: true,
      autoStart: true,
      users: { w: meWhite ? me : them, b: meWhite ? them : me },
      draft: true,
      mode,
      picksVisible: false,
      cadence: mode === "nerf" ? NERF_MODE_CADENCE : DEFAULT_CADENCE,
      draftSeed: makeSeed(),
      ...(cardOverrides ? { cardOverrides } : {}),
      draftActions: [],
    };
    await this.saveMatch(match);

    // Both clients navigate to /game/{id} and take their seat via `reconnect`;
    // the game starts once both have arrived.
    const myColor: Color = meWhite ? "w" : "b";
    const theirColor: Color = meWhite ? "b" : "w";
    send(ws, "paired", { id, color: myColor, token: match.tokens[myColor], pool: poolName, mode });
    send(opponentWs, "paired", { id, color: theirColor, token: match.tokens[theirColor], pool: poolName, mode });
  }

  private async queueLeave(ws: WebSocket, notify: boolean) {
    const session = this.sessions.get(ws) ?? (ws.deserializeAttachment() as SessionAttachment | null);
    if (!session) return;
    // Every queue entry lives under a "queue:" storage key; listing by prefix
    // also scrubs pre-split legacy keys ("queue:<pool>", no mode segment).
    const stored = await this.ctx.storage.list<QueueEntry[]>({ prefix: "queue:" });
    for (const [key, entries] of stored) {
      const next = (entries ?? []).filter((entry) => entry.attachmentId !== session.id);
      if (next.length !== (entries ?? []).length) await this.ctx.storage.put(key, next);
    }
    if (notify) send(ws, "queueCancelled");
  }

  // ---------------- house players ----------------
  //
  // Engine-driven roster (src/lib/server/bots.ts) that keeps the queue warm.
  // Design rules, all learned from the first system's crash history:
  // - Everything is alarm-driven and serialized: one pending action timer per
  //   match (botActAt), at most one house-vs-house action per tick, never a
  //   loop of engine searches.
  // - Every engine search is hard-capped (HOUSE_SEARCH_CEILING_MS = 80ms).
  // - D1 is touched only where human games already touch it (pairing reads a
  //   rating, game end records the result) plus a one-time roster seeding.
  // - Every house code path is isolated: a failure retires that match or
  //   skips that step, degrading to "bots absent", never to broken human play.
  // - With no human socket connected the roster stands down entirely.

  // A seat is ready to start when a socket holds it or a house player owns it.
  private seatReady(match: StoredMatch, color: Color): boolean {
    return !!match.bots?.[color] || !!this.connectedSession(match.id, color);
  }

  private houseTickError: string | null = null;
  private houseSeeded = false;
  // Match ids whose retire (end/delete) itself failed while acting. Kept for
  // the life of the isolate so neither the due loop nor the self-heal sweep
  // re-arms a permanently failing match into a perpetual throw/re-arm loop.
  private houseRetireFailed = new Set<string>();

  // Arm the humanlike think timer for the next pending house action: an
  // opening nerf pick, a buff-offer resolve, or a move. Never overwrites an
  // already-armed timer; clears it when no house action is pending. Cheap by
  // design (no game replay): callers pass the live game when they have one so
  // offers can be detected, and the lock-in deadline enforcement plus the
  // houseTick re-arm sweep cover the cases where they don't.
  private armBotAction(match: StoredMatch, game: NerfGame | null, now = Date.now()) {
    if (!match.bots || match.result) {
      if (match.botActAt) match.botActAt = null;
      return;
    }
    if (!match.startedAt) {
      // Opening nerf draft: any house seat that has not picked yet acts
      // after 2-8s, well inside the 15s lock-in.
      if (match.nerfOptions) {
        const pending = (["w", "b"] as Color[]).some(
          (color) => match.bots?.[color] && match.nerfPicks?.[color] == null,
        );
        if (!pending) match.botActAt = null;
        else if (!match.botActAt) match.botActAt = now + houseDraftThinkMs(randomInt);
      } else {
        match.botActAt = null;
      }
      return;
    }
    // A pending buff offer on a house seat resolves within its lock-in
    // window whoever is on turn (the shared cadence rolls offers for both
    // seats on the same move).
    if (game?.buffs) {
      const offerColor = (["w", "b"] as Color[]).find(
        (color) => match.bots?.[color] && game.buffs!.players[color].offer,
      );
      if (offerColor) {
        if (!match.botActAt) match.botActAt = now + houseDraftThinkMs(randomInt);
        return;
      }
    }
    const turn = this.activeColor(match);
    if (!match.bots[turn]) {
      match.botActAt = null;
      return;
    }
    if (match.botActAt) return;
    const clocks = this.currentClocks(match, now);
    const grace = this.movesByColor(match, turn) === 0 ? firstMoveGraceMs : 0;
    match.botActAt = now + houseThinkMs(randomInt, clocks[turn] + grace, match.setup.timeSec > 0);
  }

  // One orchestration pass, run from the alarm before match maintenance.
  private async houseTick() {
    const now = Date.now();
    if (!(await this.houseEnabled())) {
      // Paused: stop advertising seeks so the lobby shows no bots, and end any
      // bot game already in progress as an unrated draw so no human is left
      // waiting on a bot that will never move. Idempotent: once seeks are empty
      // and house games are ended, later ticks do nothing. Maintenance and the
      // alarm chain continue normally (this only skips house orchestration).
      const seeks = (await this.ctx.storage.get<HouseSeekEntry[]>(houseSeeksKey)) ?? [];
      if (seeks.length) await this.ctx.storage.put(houseSeeksKey, []);
      for (const match of await this.loadLiveMatches()) {
        if (match.result || !(match.bots?.w || match.bots?.b)) continue;
        match.clocks = this.currentClocks(match);
        match.runningSince = null;
        match.result = { winner: "draw", reason: "House players are paused for maintenance" };
        match.completedAt = Date.now();
        match.rated = false;
        try {
          await this.endMatch(match);
        } catch (err) {
          console.error("failed to end paused house game", match.id, err);
        }
      }
      return;
    }
    // Live matches only, via the in-memory index and targeted reads. Finished
    // games were skipped here anyway (see the match.result guard below), so
    // this changes nothing but the cost: no whole-table deserialize per tick.
    const matches = await this.loadLiveMatches();

    // Which personas are tied up, and the live house-game counts for the caps.
    const busy = new Set<string>();
    const liveHouseMatches: StoredMatch[] = [];
    let houseVsHouse = 0;
    let houseGames = 0;
    for (const match of matches) {
      const ids = (["w", "b"] as Color[])
        .map((color) => match.bots?.[color])
        .filter(Boolean) as string[];
      if (!ids.length || match.result) continue;
      // A house match still unstarted long past pairing (the paired human never
      // arrived at the board) frees the seat. Generous window so a slow client
      // load or a backgrounded mobile tab is not dropped mid-arrival; the
      // 30-minute maintenance sweep is the ultimate backstop.
      if (!match.startedAt && !match.nerfOptions && now - match.createdAt > 8 * 60 * 1000) {
        try {
          await this.deleteMatch(match);
        } catch {}
        continue;
      }
      for (const id of ids) busy.add(id);
      houseGames++;
      liveHouseMatches.push(match);
      if (ids.length === 2) houseVsHouse++;
    }

    // Due house actions, capped per tick (houseMaxActionsPerTick + a wall-clock
    // budget) so one alarm never runs a long batch of engine searches back to
    // back on the single thread — the CPU spike that reset the DO. Human-facing
    // actions are ordered first (filler last) and drained across follow-up
    // ticks; at most ONE house-vs-house filler action runs per tick.
    const isFiller = (m: StoredMatch) => !!(m.bots?.w && m.bots?.b);
    // The human seat of a mixed house match (undefined for house-vs-house
    // filler, which has a bot on both sides).
    const humanSeatOf = (m: StoredMatch): Color | undefined =>
      (["w", "b"] as Color[]).find((c) => !m.bots?.[c]);
    const due = liveHouseMatches
      .filter((m) => m.botActAt && m.botActAt <= now)
      .sort((a, b) => Number(isFiller(a)) - Number(isFiller(b)) || (a.botActAt ?? 0) - (b.botActAt ?? 0));
    let fillerActed = 0;
    // Bound the engine work this tick can do (see houseMaxActionsPerTick): a
    // stall used to make every game due at once and one alarm ran the whole
    // batch back to back, spiking CPU. Count real actions only (the cheap skip
    // below does not count); defer the rest to a prompt follow-up alarm.
    let actionsActed = 0;
    const tickStart = Date.now();
    let deferredDueWork = false;
    for (const match of due) {
      // A match whose retire failed is left inert (see the catch below): never
      // act on it again this isolate, so it cannot re-throw on every tick.
      if (this.houseRetireFailed.has(match.id)) continue;
      const filler = isFiller(match);
      if (filler && fillerActed >= 1) continue;
      // BUG #1: never advance a started house game while its human seat is
      // GENUINELY gone — moving would change the board (or even end the game)
      // before they return. "Gone" is the persisted disconnect signal
      // (disconnectedAt, set on detach and CLEARED on attach), never a bare
      // in-memory socket lookup: an alarm can wake this Durable Object out of
      // hibernation with the sessions map only just being rebuilt, and a
      // just-paired human who has never disconnected must not be mistaken for
      // absent — that made the bot skip its first move on every tick and never
      // play (the reported "bot game never starts"). A fresh seat has no
      // disconnectedAt entry, so the bot acts immediately; the socket lookup is
      // only a secondary guard so a present human (live socket, stale
      // timestamp) is never paused. The bot's timer stays armed across a skip
      // and fires on the first tick after they reconnect (reconnectMatch
      // re-arms it). Draft-deadline safety still runs in maintenance; pre-start
      // nerf-draft picks are harmless (clocks off).
      if (match.startedAt) {
        const humanSeat = humanSeatOf(match);
        if (
          humanSeat &&
          match.disconnectedAt[humanSeat] &&
          !this.connectedSession(match.id, humanSeat)
        ) {
          continue;
        }
      }
      // Per-tick budget: this match would run a real engine action, but we have
      // already spent the tick's action/CPU budget. Leave it (and everything
      // after it) for an immediate follow-up alarm so one tick never blocks the
      // single thread with a long batch of searches.
      if (actionsActed >= houseMaxActionsPerTick || Date.now() - tickStart > houseTickBudgetMs) {
        deferredDueWork = true;
        break;
      }
      try {
        await this.playHouseAction(match, Date.now());
        actionsActed++;
        if (filler) fillerActed++;
      } catch (err) {
        // A match that throws while acting (engine edge case, corrupt record,
        // storage hiccup) must never wedge the roster: retire it so its seats
        // free up and it drops out of the due list, instead of re-throwing on
        // every later tick.
        this.houseTickError = err instanceof Error ? err.message : String(err);
        console.error("house action failed, retiring match", match.id, err);
        try {
          const humanSeat = humanSeatOf(match);
          if (humanSeat) {
            // A human is seated: deleting the record would close their
            // socket with "Game expired" and erase a rated game with no end
            // frame. The house seat resigns through the normal end flow
            // instead, so the rating is recorded and the end frame goes out.
            if (!match.result) {
              match.clocks = this.currentClocks(match);
              match.runningSince = null;
              match.result = { winner: humanSeat, reason: "resignation" };
              match.completedAt = Date.now();
            }
            await this.endMatch(match, false);
          } else {
            // House-vs-house filler: nobody is watching a rating, delete it.
            await this.deleteMatch(match);
          }
        } catch (retireErr) {
          // Retire itself failed (storage hiccup, corrupt record). Disable the
          // match's timer and remember it so neither the due loop nor the
          // self-heal sweep re-arms it into a perpetual throw/re-arm loop.
          console.error("house retire failed, disabling match", match.id, retireErr);
          this.houseRetireFailed.add(match.id);
          try {
            match.botActAt = null;
            await this.saveMatch(match, false);
          } catch {}
        }
      }
    }
    // Deferred due actions (the per-tick budget was hit) fire on an immediate
    // follow-up rather than waiting out the full heartbeat. Their botActAt is
    // still in the past, so maintenanceAll's scheduleNextAlarm would catch them
    // anyway; this just makes the drain prompt.
    if (deferredDueWork) {
      try {
        await this.armAlarmBy(Date.now() + 300);
      } catch {}
    }
    // Self-heal: a live house game with no result and no pending action gets
    // its timer re-armed (covers records saved before a crash or deploy).
    for (const match of liveHouseMatches) {
      if (match.result || match.botActAt || this.houseRetireFailed.has(match.id)) continue;
      try {
        if (await this.finishOnFlag(match, now, false)) continue;
        this.armBotAction(match, null, now);
        if (match.botActAt) await this.saveMatch(match, false);
      } catch (err) {
        console.error("house re-arm failed", match.id, err);
      }
    }

    // Queue presence and filler games only matter while someone is looking.
    // With no human socket connected the roster stands down: seeks clear and
    // nothing new starts (live games above still play out and finish).
    let seeks = (await this.ctx.storage.get<HouseSeekEntry[]>(houseSeeksKey)) ?? [];
    const seeksBefore = seeks.length;
    seeks = seeks.filter((seek) => !busy.has(seek.userId) && now - seek.at < houseSeekTtlMs);
    if (this.humanSocketCount() === 0) {
      if (seeksBefore) await this.ctx.storage.put(houseSeeksKey, []);
      return;
    }

    const db = await this.db();
    if (!db) return;
    if (!this.houseSeeded) {
      try {
        if (!(await this.ctx.storage.get<number>(houseSeededKey))) {
          await ensureHouseUsers(db);
          await this.ctx.storage.put(houseSeededKey, now);
        }
        this.houseSeeded = true;
      } catch (err) {
        console.error("house seeding failed", err);
        return;
      }
    }

    const free = HOUSE_ROSTER.filter(
      (persona) => !busy.has(persona.userId) && !seeks.some((seek) => seek.userId === persona.userId),
    );

    // A human waiting alone in a pool gets picked up after a short beat (a
    // human opponent pairs instantly through queueJoin, so still waiting
    // means nobody came). One pickup per tick keeps the tick bounded; each
    // pool is isolated so one hiccup cannot skip the rest. Above the total
    // cap, personas leave the human waiting for a human instead.
    if (houseGames < houseTotalGamesCap) {
      let pickedUp = false;
      outer: for (const mode of QUEUE_MODES) {
        for (const poolName of Object.keys(QUEUE_POOLS)) {
          try {
            const key = this.queueKey(mode, poolName);
            const entries = (await this.ctx.storage.get<QueueEntry[]>(key)) ?? [];
            if (!entries.length) continue;
            const alive = entries.filter((entry) => this.socketForAttachment(entry.attachmentId));
            if (alive.length !== entries.length) await this.ctx.storage.put(key, alive);
            const waiting = alive[0];
            if (!waiting || now - waiting.at < houseHumanPickupMs - 500) continue;
            // Prefer the persona already seeking this pool+mode (the row the
            // human likely saw), then any seeking persona, then an idle one.
            let personaId: string | undefined;
            let index = seeks.findIndex((seek) => seek.mode === mode && seek.pool === poolName);
            if (index < 0 && seeks.length) index = 0;
            if (index >= 0) personaId = seeks.splice(index, 1)[0].userId;
            const persona = (personaId ? housePersona(personaId) : undefined) ?? free.pop();
            if (!persona) continue;
            busy.add(persona.userId);
            const humanWs = this.socketForAttachment(waiting.attachmentId);
            if (!humanWs) continue;
            // Pair first, drop the queue entry after: if pairing throws, the
            // human stays queued for the next tick instead of silently
            // sitting on "searching" forever.
            await this.pairHumanWithHouse(waiting, humanWs, poolName, mode, persona, db);
            await this.ctx.storage.put(key, alive.slice(1));
            pickedUp = true;
            break outer;
          } catch (err) {
            console.error("house pickup failed", mode, poolName, err);
          }
        }
      }
      // One pickup per tick: if it happened, come back quickly in case
      // another human is still waiting in a different pool (the heartbeat
      // alone could be up to 20s away).
      if (pickedUp) {
        try {
          await this.armAlarmBy(now + 1500);
        } catch {}
      }
    }

    // Keep 2-3 personas seeking across the two pools at all times (a mix of
    // Nerf and Buff, rotating which personas via random draw).
    while (seeks.length < houseSeekMin && free.length) {
      const persona = free.splice(randomInt(free.length), 1)[0];
      seeks.push(this.newHouseSeek(persona, now));
    }
    if (seeks.length >= houseSeekMin && seeks.length < houseSeekMax && free.length && randomInt(100) < 5) {
      const persona = free.splice(randomInt(free.length), 1)[0];
      seeks.push(this.newHouseSeek(persona, now));
    }
    // Per-mode floor: guarantee at least one seek in each pool so neither the
    // Nerf nor the Buff lobby is ever left without a house seeker (the random
    // per-seek mode roll alone can leave one mode empty). Forces the mode but
    // keeps the random pool from newHouseSeek.
    for (const mode of QUEUE_MODES) {
      if (!free.length) break;
      if (seeks.some((seek) => seek.mode === mode)) continue;
      const persona = free.splice(randomInt(free.length), 1)[0];
      seeks.push({ ...this.newHouseSeek(persona, now), mode });
    }
    await this.ctx.storage.put(houseSeeksKey, seeks);

    // Occasional house-vs-house filler so the lobby and TV look alive,
    // capped and spaced out so games never start (or end) in lockstep.
    // Tier 2 / M4 cutover (reversible): when the arena owns bot-vs-bot, the DO
    // stops spawning its own filler and lets the arena supply it (streamed in
    // via /arena). Flip ARENA_OWNS_FILLER back off and the DO resumes filler on
    // the next tick — no code change, so the arena being down never means an
    // empty lobby. Bot-vs-human pickup + house seeks above are unaffected.
    const arenaOwnsFiller = this.env.ARENA_OWNS_FILLER === "true" && this.env.ARENA_INGEST_ENABLED === "true";
    if (!arenaOwnsFiller && houseVsHouse < houseVsHouseCap && houseGames + 1 < houseTotalGamesCap && free.length >= 2) {
      try {
        const nextAt = (await this.ctx.storage.get<number>(houseNextFillerKey)) ?? 0;
        if (now >= nextAt) {
          const a = free.splice(randomInt(free.length), 1)[0];
          const b = free.splice(randomInt(free.length), 1)[0];
          await this.startHouseVsHouseGame(a, b, db);
          await this.ctx.storage.put(houseNextFillerKey, now + 4_000 + randomInt(6_000));
        }
      } catch (err) {
        console.error("house filler start failed", err);
      }
    }
  }

  // The house player's pending action lands: an opening nerf pick, a buff
  // offer resolve, an occasional buff activation, or a move. Exactly one
  // action per invocation; every follow-up re-arms through armBotAction.
  // Ask the OCI engine service for a house move. Returns null (never throws)
  // whenever the feature is off, the box is slow/unreachable, the reply is bad,
  // or the engine versions disagree — the caller then falls back to the local
  // engine. The AbortController timeout is what keeps a stalled box from ever
  // holding the alarm tick; the `await` itself yields the DO thread so live
  // sockets are serviced while the remote search runs.
  private async remoteHouseMove(
    match: StoredMatch,
    skill: HouseSkill,
    remainingClockMs?: number,
  ): Promise<Move | null> {
    if (this.env.HOUSE_ENGINE_REMOTE !== "true" || !this.env.HOUSE_ENGINE_URL) return null;
    const ctl = new AbortController();
    const timer = setTimeout(() => ctl.abort(), HOUSE_ENGINE_TIMEOUT_MS);
    try {
      const res = await fetch(`${this.env.HOUSE_ENGINE_URL}/move`, {
        method: "POST",
        signal: ctl.signal,
        headers: {
          "content-type": "application/json",
          ...(this.env.HOUSE_ENGINE_TOKEN
            ? { authorization: `Bearer ${this.env.HOUSE_ENGINE_TOKEN}` }
            : {}),
        },
        body: JSON.stringify({
          match: serializeMatchForEngine(match),
          skill,
          remainingClockMs,
          replayVersion: REPLAY_VERSION,
        }),
      });
      if (!res.ok) return null; // 409 version mismatch / 5xx -> local fallback
      const data = (await res.json()) as { move?: Move | null };
      return data.move ?? null;
    } catch {
      return null; // timeout / network / parse -> local fallback
    } finally {
      clearTimeout(timer);
    }
  }

  private async playHouseAction(match: StoredMatch, now = Date.now()) {
    match.botActAt = null;
    if (match.result) return;

    // Opening nerf draft picks (no game replay needed).
    if (!match.startedAt) {
      if (!match.nerfOptions) return;
      let picked = false;
      for (const color of ["w", "b"] as Color[]) {
        if (!match.bots?.[color] || match.nerfPicks?.[color] != null) continue;
        const options = match.nerfOptions[color];
        const tierOf = (id: string) => PLAYABLE_NERFS.find((nerf) => nerf.id === id)?.tier ?? 5;
        const index = houseNerfPickIndex([tierOf(options[0]), tierOf(options[1])], randomInt);
        match.nerfPicks = { ...(match.nerfPicks ?? {}), [color]: index };
        picked = true;
        const opp: Color = color === "w" ? "b" : "w";
        if (match.nerfPicks[opp] == null) this.broadcast(match, "dtNerfPicked", { color });
      }
      if (!picked) return;
      if (match.nerfPicks?.w != null && match.nerfPicks?.b != null) {
        await this.finalizeNerfDraft(match);
        return;
      }
      await this.saveMatch(match);
      return;
    }

    if (await this.finishOnFlag(match, now, false)) return;
    // A stale or failed replay ends the game gracefully inside gameForPlay
    // (draw, end frame, recorded); nothing left for the house seat to do.
    let game = await this.gameForPlay(match);
    if (!game) return;
    if (game.result) {
      // Derived but unrecorded result (should not happen): settle it.
      match.clocks = this.currentClocks(match, now);
      match.runningSince = null;
      match.result = game.result;
      match.completedAt = now;
      await this.endMatch(match);
      return;
    }

    // A pending buff offer resolves first (it may not even be our turn). A
    // card that throws while the AI evaluates or picks it must never wedge the
    // bot: fall back to banking the offer, which is always a safe skip.
    for (const color of ["w", "b"] as Color[]) {
      if (!match.bots?.[color] || !game.buffs?.players[color].offer) continue;
      try {
        const choice = aiDraftChoice(game, color);
        if (choice?.action === "pick") await this.resolveDraftPick(match, game, color, choice.index);
        else await this.resolveDraftBank(match, game, color);
      } catch (err) {
        console.error("house draft resolve failed, banking offer", match.id, err);
        await this.resolveDraftBank(match, game, color);
      }
      return; // settleDraftAction armed the next action and saved
    }

    const color = game.board.turn;
    const personaId = match.bots?.[color];
    if (!personaId) {
      this.armBotAction(match, game, now);
      await this.saveMatch(match, false);
      return;
    }
    const persona = housePersona(personaId);
    if (!persona) throw new Error(`unknown house persona ${personaId}`);

    // Sometimes fire a held buff instead of moving. aiChooseBuffActivation
    // applies its own worth-it gates; the extra coin keeps house players from
    // dumping every card the moment it clears the bar. A buff that throws
    // mid-activation must not wedge the bot or corrupt the move it plays next.
    if (match.draft && game.buffs && randomInt(100) < 40) {
      try {
        const activation = aiChooseBuffActivation(game, color);
        if (activation) {
          const ps = game.buffs.players[color];
          const inst = ps.buffs[activation.buffIndex];
          const theirs = game.buffs.players[color === "w" ? "b" : "w"];
          const mineBefore = ps.buffs.length;
          const theirsBefore = theirs.buffs.length;
          if (activateBuff(game, color, activation.buffIndex, activation.picks)) {
            this.markBuffRevealed(inst);
            for (const added of ps.buffs.slice(mineBefore)) this.markBuffRevealed(added);
            for (const added of theirs.buffs.slice(theirsBefore)) this.markBuffRevealed(added);
            match.draftActions = [
              ...(match.draftActions ?? []),
              { ply: match.moves.length, color, a: "use", buffIndex: activation.buffIndex, picks: activation.picks },
            ];
            await this.settleDraftAction(match, game, null, {
              color,
              buffIndex: activation.buffIndex,
              picks: activation.picks,
              card: { id: inst.id, tier: inst.tier as number },
            });
            return;
          }
        }
      } catch (err) {
        // Discard the possibly-mutated replica and rebuild a clean one from the
        // stored record (the failed activation was never appended, so the
        // rebuild is the pre-activation position), then fall through to a
        // normal move so the bot still acts this turn.
        console.error("house buff activation failed, skipping to a move", match.id, err);
        const fresh = this.gameFromMatch(match);
        if (!fresh || fresh.result) {
          this.armBotAction(match, null, now);
          await this.saveMatch(match, false);
          return;
        }
        game = fresh;
      }
    }

    // The move: engine-picked inside a hard-capped budget (see bots.ts). A
    // throw or a null pick (an engine edge case) can never leave the bot idle:
    // fall back to any legal move, and only end the game when there truly is
    // no legal move at all.
    const clocks = this.currentClocks(match, now);
    const remaining = match.setup.timeSec ? clocks[color] : undefined;
    let move: Move | null = null;
    if (this.env.HOUSE_ENGINE_REMOTE === "true") {
      const remote = await this.remoteHouseMove(match, persona.skill, remaining);
      // The await above yielded the DO thread; the match may have ended (resign,
      // disconnect, flag) while the remote search ran. Bail if so.
      if (match.result) return;
      // Treat the OCI reply as untrusted: accept only a move that is legal in
      // our own reconstruction, and commit our LOCAL instance (never the wire
      // object). A desynced/tampered move simply isn't found -> local fallback.
      if (remote) move = legalMoves(game).find((m) => sameMove(m, remote)) ?? null;
    }
    if (!move) {
      try {
        move = pickHouseMove(game, persona.skill, randomInt, remaining);
      } catch (err) {
        console.error("house move pick failed, using a legal fallback", match.id, err);
      }
    }
    if (!move) {
      const legal = legalMoves(game);
      if (legal.length) {
        move = legal[randomInt(legal.length)];
      } else {
        // No legal move but no result — should be unreachable; end through the
        // normal flow rather than wedge the match.
        match.clocks = clocks;
        match.runningSince = null;
        match.result = resign(game, color).result;
        match.completedAt = now;
        await this.endMatch(match);
        return;
      }
    }
    await this.commitMove(match, game, color, move, moveToUCI(move));
  }

  private newHouseSeek(persona: HousePersona, now: number): HouseSeekEntry {
    const { pool, mode } = pickHouseSeek(randomInt);
    return {
      userId: persona.userId,
      name: persona.name,
      pool,
      mode,
      rating: houseSeedRating(persona),
      avatar: persona.avatar,
      at: now,
    };
  }

  // The persona's SeatUser for a match seat, with its live rating in the
  // pool's mode bucket (one D1 read, event-scale only: pairing and filler
  // starts, never per tick).
  private async houseSeatUser(db: D1Database, persona: HousePersona, mode: DraftMode): Promise<SeatUser> {
    try {
      const row = await this.seatCategoryRating(db, persona.userId, mode);
      if (row) {
        return {
          id: persona.userId,
          name: persona.name,
          rating: row.rating,
          rd: row.rd,
          vol: row.vol,
          avatar: row.avatar ?? persona.avatar,
        };
      }
    } catch {}
    const rating = houseSeedRating(persona);
    return { id: persona.userId, name: persona.name, rating, rd: 150, vol: 0.06, avatar: persona.avatar };
  }

  // A rated queue match against a house player, identical to a human-vs-human
  // queue match except for the house seat markers.
  private async newHouseMatchRecord(
    poolName: string,
    mode: DraftMode,
    seats: { users: Partial<Record<Color, SeatUser>>; bots: Partial<Record<Color, string>> },
  ): Promise<StoredMatch> {
    const pool = QUEUE_POOLS[poolName];
    const id = await this.newCode(8);
    const cardSnap = await this.cardOverridesSnapshot();
    const cardOverrides = this.draftPoolStamp(cardSnap);
    return {
      id,
      setup: {
        ...(mode === "buff"
          ? { whiteNerfId: UNRESTRICTED_NERF.id, blackNerfId: UNRESTRICTED_NERF.id }
          : pickNerfIds(cardSnap.nerfOff)),
        seed: makeSeed(),
        timeSec: pool.timeSec,
        incrementSec: pool.incrementSec,
      },
      tokens: { w: newToken(), b: newToken() },
      disconnectedAt: {},
      opponentGoneNotified: {},
      moves: [],
      result: null,
      clocks: { w: pool.timeSec * 1000, b: pool.timeSec * 1000 },
      runningSince: null,
      drawOfferBy: null,
      createdAt: Date.now(),
      startedAt: null,
      completedAt: null,
      replayVersion: REPLAY_VERSION,
      rated: true,
      autoStart: true,
      users: seats.users,
      draft: true,
      mode,
      picksVisible: false,
      cadence: mode === "nerf" ? NERF_MODE_CADENCE : DEFAULT_CADENCE,
      draftSeed: makeSeed(),
      ...(cardOverrides ? { cardOverrides } : {}),
      draftActions: [],
      bots: seats.bots,
    };
  }

  // Pair a queued human with a house player. The human gets the usual
  // "paired" frame and takes their seat via reconnect; the house seat counts
  // as arrived, so the game starts the moment the human does.
  private async pairHumanWithHouse(
    waiting: QueueEntry,
    humanWs: WebSocket,
    poolName: string,
    mode: DraftMode,
    persona: HousePersona,
    db: D1Database,
  ) {
    if (!QUEUE_POOLS[poolName]) return;
    const human: SeatUser = {
      id: waiting.userId,
      name: waiting.username,
      rating: waiting.rating,
      rd: waiting.rd,
      vol: waiting.vol,
      avatar: waiting.avatar ?? null,
    };
    const house = await this.houseSeatUser(db, persona, mode);
    const humanWhite = randomInt(2) === 0;
    const match = await this.newHouseMatchRecord(poolName, mode, {
      users: { w: humanWhite ? human : house, b: humanWhite ? house : human },
      bots: humanWhite ? { b: persona.userId } : { w: persona.userId },
    });
    await this.saveMatch(match);
    const color: Color = humanWhite ? "w" : "b";
    send(humanWs, "paired", { id: match.id, color, token: match.tokens[color], pool: poolName, mode });
  }

  private async startHouseVsHouseGame(a: HousePersona, b: HousePersona, db: D1Database) {
    const { pool, mode } = pickHouseSeek(randomInt);
    const aWhite = randomInt(2) === 0;
    const [white, black] = aWhite ? [a, b] : [b, a];
    const match = await this.newHouseMatchRecord(pool, mode, {
      users: { w: await this.houseSeatUser(db, white, mode), b: await this.houseSeatUser(db, black, mode) },
      bots: { w: white.userId, b: black.userId },
    });
    // Nerf mode opens with the nerf draft (the house seats pick like anyone
    // else); Buff mode starts outright.
    if (mode !== "buff") {
      await this.beginNerfDraft(match);
      return;
    }
    const now = Date.now();
    match.startedAt = now;
    match.runningSince = now;
    this.armBotAction(match, null, now);
    await this.saveMatch(match);
  }

  // ---- Arena ingestion (Tier 2 / M2) ----
  // The OCI arena runs bot-vs-bot games and POSTs here: /arena/games (periodic
  // registry of its live games, for lobby/TV) and /arena/end (a finished game,
  // to archive + rate). Auth via ARENA_INGEST_TOKEN. Gated by ARENA_INGEST_ENABLED
  // (archive+rating) and ARENA_LOBBY_ENABLED (visibility), so it ships dark.
  private async handleArena(request: Request, url: URL): Promise<Response> {
    if (request.method !== "POST") return new Response("method not allowed", { status: 405 });
    const token = this.env.ARENA_INGEST_TOKEN;
    if (!token || request.headers.get("authorization") !== `Bearer ${token}`) {
      return new Response("unauthorized", { status: 401 });
    }
    const ingest = this.env.ARENA_INGEST_ENABLED === "true";
    // The arena should spawn only when ingestion is on AND a human is present to
    // see the lobby (mirror the DO's own stand-down). Told to the arena so it
    // pauses otherwise.
    const enabled = ingest && this.humanSocketCount() > 0;

    if (url.pathname === "/arena/games") {
      let body: { games?: ExternalGameMeta[] };
      try {
        body = (await request.json()) as { games?: ExternalGameMeta[] };
      } catch {
        return Response.json({ error: "bad_json" }, { status: 400 });
      }
      if (ingest) {
        const now = Date.now();
        const next = new Map<string, { meta: ExternalGameMeta; at: number }>();
        for (const g of body.games ?? []) {
          // Only house accounts may be projected — a forged id can never inject
          // a fake game for a real user.
          if (!g || !isHouseUserId(g.seats?.w?.userId) || !isHouseUserId(g.seats?.b?.userId)) continue;
          next.set(g.id, { meta: g, at: now });
        }
        this.externalGames = next;
      } else {
        this.externalGames.clear();
      }
      const lobby = this.env.ARENA_LOBBY_ENABLED === "true";
      // Tell the arena which of its games a human is spectating so it streams
      // per-move frames for those only (Tier 2 / M3). Empty unless the lobby is
      // on (you can only watch a game the lobby surfaced).
      const watch = ingest && lobby ? this.externalWatchedIds() : [];
      return Response.json({ enabled, lobby, watch });
    }

    if (url.pathname === "/arena/frame") {
      // Spectator relay (Tier 2 / M3). Advance the watched game's replica and
      // fan the event out to its watchers. Gated by ingest + lobby; a frame for
      // an unknown/unwatched game is a harmless no-op.
      if (!ingest || this.env.ARENA_LOBBY_ENABLED !== "true") return Response.json({ ok: false, ingest: false });
      let body: { frame?: ArenaFrame };
      try {
        body = (await request.json()) as { frame?: ArenaFrame };
      } catch {
        return Response.json({ error: "bad_json" }, { status: 400 });
      }
      const frame = body.frame;
      if (!frame || typeof frame.id !== "string") return Response.json({ error: "bad_frame" }, { status: 400 });
      try {
        if (frame.kind === "snapshot") this.ingestExternalSnapshot(frame);
        else if (frame.kind === "move") this.applyExternalMove(frame.id, frame.ply, frame.u, frame.clocks);
        else if (frame.kind === "draft") this.applyExternalDraft(frame.id, frame.action, frame.card);
      } catch (err) {
        console.error("arena frame failed", frame.id, err);
        return Response.json({ ok: false, reason: "frame_failed" });
      }
      return Response.json({ ok: true });
    }

    if (url.pathname === "/arena/end") {
      if (!ingest) return Response.json({ ok: false, ingest: false });
      let body: { record?: ArenaEndRecord };
      try {
        body = (await request.json()) as { record?: ArenaEndRecord };
      } catch {
        return Response.json({ error: "bad_json" }, { status: 400 });
      }
      const rec = body.record;
      if (!rec || !isHouseUserId(rec.bots?.w) || !isHouseUserId(rec.bots?.b)) {
        return Response.json({ error: "bad_record" }, { status: 400 });
      }
      this.externalGames.delete(rec.id);
      // Spectators (if any) see the game end with the revealed nerfs + held
      // buffs, then the replica is dropped (Tier 2 / M3). Independent of the
      // archive write below so a DB hiccup never strands a watched game "live".
      this.endExternalForWatchers(rec);
      if (this.arenaArchived.has(rec.id)) return Response.json({ ok: true, dup: true });
      const db = await this.db();
      if (!db) return Response.json({ ok: false, reason: "no_db" });
      try {
        // Same call endMatch uses — applies Glicko to both house accounts and
        // writes the archive row (PG via Hyperdrive, else D1). Bot-only, so a
        // bad arena can move house ratings but never a human's.
        await recordFinishedGame(
          db,
          {
            id: rec.id,
            whiteUserId: rec.bots.w,
            blackUserId: rec.bots.b,
            whiteName: rec.seats.w.name,
            blackName: rec.seats.b.name,
            whiteNerfId: rec.setup.whiteNerfId,
            blackNerfId: rec.setup.blackNerfId,
            seed: rec.setup.seed,
            timeSec: rec.setup.timeSec,
            incrementSec: rec.setup.incrementSec,
            moves: rec.moves,
            winner: rec.result.winner,
            reason: rec.result.reason,
            rated: true,
            ruleset: "draft",
            ratingCategory: rec.mode,
            startedAt: rec.startedAt,
            completedAt: rec.completedAt,
          },
          this.env.HYPERDRIVE?.connectionString,
        );
        this.arenaArchived.add(rec.id);
        if (this.arenaArchived.size > 2000) this.arenaArchived.clear();
      } catch (err) {
        console.error("arena game record failed", rec.id, err);
        return Response.json({ ok: false, reason: "record_failed" });
      }
      return Response.json({ ok: true });
    }

    return new Response("not found", { status: 404 });
  }

  // ---- Arena spectating (Tier 2 / M3) ----

  // Distinct arena game ids a human is currently watching. Told to the arena so
  // it streams per-move frames for these only.
  private externalWatchedIds(): string[] {
    const ids = new Set<string>();
    for (const [ws, s] of this.sessions) {
      if (ws.readyState === WebSocket.OPEN && s.watching && this.externalGames.has(s.watching)) ids.add(s.watching);
    }
    return [...ids];
  }

  // Relay a frame to every socket watching a given game id (the by-id twin of
  // sendWatchers, which keys off a StoredMatch).
  private sendWatchersById(id: string, t: string, d?: unknown) {
    for (const [ws, session] of this.sessions) {
      if (session.watching === id && ws.readyState === WebSocket.OPEN) send(ws, t, d);
    }
  }

  // Build the ephemeral replica StoredMatch for a watched arena game from the
  // arena's snapshot. Shaped exactly like a house-vs-house match so every
  // existing spectator helper (gameFromMatch, draftStateFor, publicDraftActions,
  // playersPayload, currentClocks) works on it unchanged. Never persisted.
  private buildExternalMatch(snap: ArenaSnapshot): StoredMatch {
    const seatUser = (s: ExternalSeat): SeatUser => ({
      id: s.userId,
      name: s.name,
      rating: s.rating,
      rd: 150,
      vol: 0.06,
      avatar: housePersona(s.userId)?.avatar ?? null,
    });
    const now = Date.now();
    return {
      id: snap.id,
      setup: {
        whiteNerfId: snap.setup.whiteNerfId,
        blackNerfId: snap.setup.blackNerfId,
        seed: snap.setup.seed,
        timeSec: snap.setup.timeSec,
        incrementSec: snap.setup.incrementSec,
      },
      tokens: { w: "", b: "" },
      disconnectedAt: {},
      opponentGoneNotified: {},
      moves: [...snap.moves],
      result: null,
      clocks: { w: snap.clocks.w, b: snap.clocks.b },
      runningSince: snap.startedAt ? now : null,
      drawOfferBy: null,
      createdAt: snap.startedAt || now,
      startedAt: snap.startedAt || null,
      completedAt: null,
      replayVersion: REPLAY_VERSION,
      rated: true,
      autoStart: true,
      users: { w: seatUser(snap.seats.w), b: seatUser(snap.seats.b) },
      draft: true,
      mode: snap.mode,
      picksVisible: false,
      cadence: snap.cadence,
      draftSeed: snap.draftSeed,
      draftActions: [...snap.draftActions],
      bots: { w: snap.seats.w.userId, b: snap.seats.b.userId },
    };
  }

  // A started snapshot arrived: (re)build the replica and bootstrap every socket
  // already waiting on this game with a wstart (they watched before the arena
  // began streaming). Ignored for pre-start games — the DO can't reconstruct a
  // board whose nerfs are still hidden, so those spectators keep waiting.
  private ingestExternalSnapshot(snap: ArenaSnapshot) {
    if (!isHouseUserId(snap.seats?.w?.userId) || !isHouseUserId(snap.seats?.b?.userId)) return;
    if (!snap.startedAt) return;
    const match = this.buildExternalMatch(snap);
    this.externalMatches.set(snap.id, match);
    for (const [ws, session] of this.sessions) {
      if (session.watching === snap.id && ws.readyState === WebSocket.OPEN) this.sendWstart(ws, match);
    }
  }

  // Advance a watched game's replica by one move and relay it. gameFromMatch
  // re-derives turn + spectator reveals from the full record (the same replay
  // the DO does for its own games), so a freshly revealed passive reaches
  // watchers via dtState. No `end` here — /arena/end sends it with the ratings.
  private applyExternalMove(id: string, ply: number, uci: string, clocks: Record<Color, number>) {
    const match = this.externalMatches.get(id);
    if (!match || match.result) return;
    // Apply only the next expected move (mirrors the client's own ply check): a
    // stale/duplicate frame that raced the bootstrap snapshot is dropped, not
    // double-applied. A gap (frame lost) leaves the replica where it is.
    if (typeof ply === "number" && ply !== match.moves.length + 1) return;
    // Rebuild the PRE-move game and run the move through the engine here, so
    // hidden passives that granted the move (via) or fired on it (a capture
    // detonation) are revealed to watchers BEFORE the move frame, exactly
    // like commitMove: a spectator replica applying the move without the
    // card's identity would desync its board, and dtState cannot repair a
    // board. The rebuild count is unchanged (pre-move instead of post-move).
    let game: NerfGame | null = null;
    try {
      game = this.gameFromMatch(match);
    } catch {}
    if (game && !game.result) {
      const move = moveByUci(game, uci);
      if (move && match.draft && game.buffs) {
        if (this.markViaRevealed(game, move)) this.sendWatcherDraftStateById(id, match, game);
        const preBuffs = JSON.parse(JSON.stringify(game.buffs)) as BuffMatchState;
        setDraftPoolOverrides(match.cardOverrides ?? null);
        try {
          game = playMove(game, move);
        } finally {
          setDraftPoolOverrides(null);
        }
        if (this.revealFiredHooks(game, preBuffs)) {
          this.sendWatcherDraftStateById(id, match, { buffs: preBuffs } as unknown as NerfGame);
        }
      } else {
        game = move ? playMove(game, move) : null;
      }
    }
    match.moves.push(uci);
    if (clocks && typeof clocks.w === "number" && typeof clocks.b === "number") {
      match.clocks = { w: clocks.w, b: clocks.b };
    }
    if (game) {
      match.turnColor = game.board.turn;
      if (game.result) match.result = game.result;
    }
    match.runningSince = match.result ? null : Date.now();
    this.sendWatchersById(id, "move", {
      u: uci,
      ply: match.moves.length,
      wc: Math.round(match.clocks.w),
      bc: Math.round(match.clocks.b),
      ...(game ? { f: fnv1a(positionKey(game.board)) } : {}),
    });
    if (game?.buffs) {
      const state = this.draftStateFor(game, match, "spectator");
      if (state) this.sendWatchersById(id, "dtState", { state });
    }
  }

  // Spectator-filtered dtState for an arena-relayed match id.
  private sendWatcherDraftStateById(id: string, match: StoredMatch, game: NerfGame) {
    const state = this.draftStateFor(game, match, "spectator");
    if (state) this.sendWatchersById(id, "dtState", { state });
  }

  // Advance a watched game's replica by one draft action and relay the
  // spectator-filtered frame, reusing the exact masking the native path uses
  // (publicDraftActions for a pick, the fired card for a use).
  private applyExternalDraft(id: string, action: StoredDraftAction, card?: { id: string; tier: number }) {
    const match = this.externalMatches.get(id);
    if (!match || match.result) return;
    match.draftActions = [...(match.draftActions ?? []), action];
    let game: NerfGame | null = null;
    try {
      game = this.gameFromMatch(match);
    } catch {}
    if (game) {
      match.turnColor = game.board.turn;
      if (game.result) match.result = game.result;
    }
    if (action.a === "use") {
      this.sendWatchersById(id, "dtUsed", {
        color: action.color,
        buffIndex: action.buffIndex,
        picks: action.picks,
        ...(card ? { card } : {}),
      });
    } else if (action.a === "pick") {
      const masked = this.publicDraftActions(match, "spectator");
      const last = masked[masked.length - 1];
      const cards = last && last.a === "pick" ? last.cards : [];
      this.sendWatchersById(id, "dtResolved", { color: action.color, kind: "picked", cards });
    } else {
      this.sendWatchersById(id, "dtResolved", { color: action.color, kind: "banked" });
    }
    if (game?.buffs) {
      const state = this.draftStateFor(game, match, "spectator");
      if (state) this.sendWatchersById(id, "dtState", { state });
    }
  }

  // Send one spectator their opening wstart from a (replica or native) match.
  // Factored out of watchMatch so an external snapshot can flush it to sockets
  // that were waiting for the arena to start streaming.
  private sendWstart(ws: WebSocket, match: StoredMatch) {
    const id = match.id;
    const clocks = this.currentClocks(match);
    let draftExtras: Record<string, unknown> | null = null;
    if (match.draft) {
      const game = match.startedAt ? this.gameFromMatch(match) : null;
      draftExtras = {
        draft: true,
        ...(match.mode ? { mode: match.mode } : {}),
        dtActions: this.publicDraftActions(match, "spectator"),
        ...(game?.buffs ? { dtState: this.draftStateFor(game, match, "spectator") } : {}),
      };
    }
    send(ws, "wstart", {
      id,
      timeSec: match.setup.timeSec,
      incrementSec: match.setup.incrementSec,
      wc: Math.round(clocks.w),
      bc: Math.round(clocks.b),
      moves: match.moves,
      players: this.playersPayload(match),
      rated: !!match.rated,
      started: !!match.startedAt,
      result: match.result,
      watchers: this.watcherCount(id),
      watcherNames: this.watcherInfo(id).names,
      spectatorChat: match.spectatorChat ?? [],
      ...(match.result ? { nerfs: { w: match.setup.whiteNerfId, b: match.setup.blackNerfId } } : {}),
      ...(draftExtras ?? {}),
    });
  }

  // A watched arena game finished: reveal nerfs + held buffs to its spectators
  // with the result, then drop the replica. Rebuilds the game from the
  // authoritative end record so held buffs are exact even if a mid-game frame
  // was dropped.
  private endExternalForWatchers(rec: ArenaEndRecord) {
    const match = this.externalMatches.get(rec.id);
    this.externalMatches.delete(rec.id);
    if (!match) return; // nobody was watching
    match.moves = [...rec.moves];
    if (rec.draftActions) match.draftActions = [...rec.draftActions];
    match.result = rec.result;
    let draftBuffs: Record<Color, { id: string; tier: number; spent?: boolean; nullified?: boolean }[]> | null = null;
    try {
      const game = this.gameFromMatch(match);
      if (game?.buffs) {
        const held = (color: Color) =>
          game.buffs!.players[color].buffs.map((b) => ({
            id: b.id,
            tier: b.tier as number,
            ...(b.spent ? { spent: true } : {}),
            ...(b.nullified ? { nullified: true } : {}),
          }));
        draftBuffs = { w: held("w"), b: held("b") };
      }
    } catch {}
    this.sendWatchersById(rec.id, "end", {
      result: rec.result,
      wc: Math.round(match.clocks.w),
      bc: Math.round(match.clocks.b),
      nerfs: { w: rec.setup.whiteNerfId, b: rec.setup.blackNerfId },
      ...(draftBuffs ? { draftBuffs } : {}),
    });
  }

  // Fresh (non-expired) arena games as lobby liveGames entries (Tier 2 / M2).
  private externalLiveGames(now: number): Array<{
    id: string;
    players: ReturnType<GameServer["playersPayload"]>;
    rated: boolean;
    draft: boolean;
    mode?: DraftMode;
    timeSec: number;
    incrementSec: number;
    moves: number;
    watchers: number;
  }> {
    if (this.env.ARENA_LOBBY_ENABLED !== "true") return [];
    const games = [];
    for (const { meta, at } of this.externalGames.values()) {
      if (now - at > EXTERNAL_GAME_TTL_MS) continue;
      const seat = (c: Color) => ({
        name: meta.seats[c].name,
        rating: Math.round(meta.seats[c].rating),
        avatar: housePersona(meta.seats[c].userId)?.avatar ?? null,
      });
      games.push({
        id: meta.id,
        players: { w: seat("w"), b: seat("b") },
        rated: true,
        draft: true,
        mode: meta.mode,
        timeSec: meta.timeSec,
        incrementSec: meta.incrementSec,
        moves: meta.moves,
        watchers: this.watcherCount(meta.id),
      });
    }
    return games;
  }

  // ---------------- rematch ----------------

  // Withdraw a pending rematch offer. Only the player who made the offer can
  // cancel it, and only while no rematch game has been created yet.
  private async rematchCancel(ws: WebSocket) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return;
    if (match.rematchedTo) return;
    if (match.rematchOfferBy !== session.color) return;
    match.rematchOfferBy = null;
    await this.saveMatch(match, false);
    this.broadcast(match, "rematchCancelled", { color: session.color });
  }

  private async rematchRequest(ws: WebSocket) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before requesting a rematch.");
    if (!match.result) return error(ws, "not_over", "The game is still in progress.");
    if (match.rematchedTo) return error(ws, "rematch_done", "A rematch has already started.");

    const opponentColor: Color = session.color === "w" ? "b" : "w";
    if (match.rematchOfferBy === session.color) return;
    if (match.rematchOfferBy !== opponentColor) {
      if (!this.connectedSession(match.id, opponentColor)) {
        return error(ws, "opponent_gone", "Your opponent has left.");
      }
      match.rematchOfferBy = session.color;
      await this.saveMatch(match, false);
      this.broadcast(match, "rematchOffer", { color: session.color });
      return;
    }

    // Both agreed: new game with colors swapped, fresh rules and seed.
    const users: StoredMatch["users"] = {};
    if (match.users?.b) users.w = { ...match.users.b };
    if (match.users?.w) users.b = { ...match.users.w };
    const db = await this.db();
    if (db) {
      for (const color of ["w", "b"] as Color[]) {
        const seat = users[color];
        if (!seat) continue;
        const row = await this.seatCategoryRating(db, seat.id, this.matchRatingCategory(match));
        if (row) {
          seat.rating = row.rating;
          seat.rd = row.rd;
          seat.vol = row.vol;
          seat.avatar = row.avatar;
        }
      }
    }

    const id = await this.newCode(match.rated ? 8 : 5);
    // A rematch is a NEW match: it takes the current overrides snapshot, not
    // the finished game's, so fresh card edits reach rematches too.
    const cardSnap = await this.cardOverridesSnapshot();
    const cardOverrides = match.draft ? this.draftPoolStamp(cardSnap) : undefined;
    const rematch: StoredMatch = {
      id,
      setup: {
        ...(match.mode === "buff"
          ? { whiteNerfId: UNRESTRICTED_NERF.id, blackNerfId: UNRESTRICTED_NERF.id }
          : pickNerfIds(cardSnap.nerfOff)),
        seed: makeSeed(),
        timeSec: match.setup.timeSec,
        incrementSec: match.setup.incrementSec,
      },
      tokens: { w: newToken(), b: newToken() },
      disconnectedAt: {},
      opponentGoneNotified: {},
      moves: [],
      result: null,
      clocks: { w: match.setup.timeSec * 1000, b: match.setup.timeSec * 1000 },
      runningSince: null,
      drawOfferBy: null,
      createdAt: Date.now(),
      startedAt: null,
      completedAt: null,
      replayVersion: REPLAY_VERSION,
      rated: match.rated,
      autoStart: true,
      users,
      ...(match.draft
        ? {
            draft: true,
            ...(match.mode ? { mode: match.mode } : {}),
            picksVisible: !!match.picksVisible,
            cadence: match.mode === "nerf" ? NERF_MODE_CADENCE : DEFAULT_CADENCE,
            draftSeed: makeSeed(),
            ...(cardOverrides ? { cardOverrides } : {}),
            draftActions: [],
          }
        : {}),
    };
    await this.saveMatch(rematch);
    match.rematchOfferBy = null;
    match.rematchedTo = id;
    await this.saveMatch(match, false);

    send(this.connectedSession(match.id, "w"), "rematched", { id, color: "b", token: rematch.tokens.b });
    send(this.connectedSession(match.id, "b"), "rematched", { id, color: "w", token: rematch.tokens.w });
  }

  // ---------------- chat ----------------

  // Per-socket chat throttle; in-memory only, so at worst a hibernation wake
  // resets the window.
  private lastChatAt = new Map<string, number>();

  private async chatMessage(ws: WebSocket, data: unknown) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before chatting.");
    const raw = String((data as { text?: unknown } | undefined)?.text ?? "").trim();
    if (!raw) return;
    const now = Date.now();
    if (now - (this.lastChatAt.get(session.id) ?? 0) < 500) return;
    this.lastChatAt.set(session.id, now);

    const name = match.users?.[session.color]?.name ?? (session.color === "w" ? "White" : "Black");
    const clipped = raw.slice(0, 200);
    // Shadow-mute (Lichess-style): a chat-muted player sees their own message
    // echoed back, but it is neither stored nor shown to anyone else.
    if (session.mutedUntil && session.mutedUntil > Date.now()) {
      send(ws, "chat", { color: session.color, name, text: clipped, at: now } satisfies ChatEntry);
      return;
    }
    // Censor profanity before it is stored or relayed, and keep the original
    // in chat_flags so a moderator can review repeat offenders later.
    const matched = findProfanity(clipped);
    const text = matched.length ? censorText(clipped) : clipped;
    if (matched.length) {
      const db = await this.db();
      if (db) {
        try {
          await db
            .prepare(
              `INSERT INTO chat_flags (id, match_id, user_id, username, color, text, matched_words, created_at)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
            )
            .bind(crypto.randomUUID(), match.id, session.userId ?? null, name, session.color, clipped, matched.join(","), now)
            .run();
        } catch (err) {
          console.error("failed to record chat flag", match.id, err);
        }
      }
    }
    const entry: ChatEntry = { color: session.color, name, text, at: now };
    match.chat = [...(match.chat ?? []), entry].slice(-50);
    await this.saveMatch(match, false);
    this.broadcast(match, "chat", entry);
  }

  // Chat between spectators. Relayed only to sockets watching the same game,
  // so the players can't read it (no coaching from the rail).
  private async spectatorChatMessage(ws: WebSocket, data: unknown) {
    const session = this.session(ws);
    const match = session.watching ? await this.loadMatch(session.watching) : null;
    if (!match) return error(ws, "not_watching", "Watch a game before chatting.");
    const raw = String((data as { text?: unknown } | undefined)?.text ?? "").trim();
    if (!raw) return;
    const now = Date.now();
    if (now - (this.lastChatAt.get(session.id) ?? 0) < 500) return;
    this.lastChatAt.set(session.id, now);

    const name = session.username ?? "Anonymous";
    const clipped = raw.slice(0, 200);
    // Shadow-mute works here too: the muted watcher sees only their own echo.
    if (session.mutedUntil && session.mutedUntil > Date.now()) {
      send(ws, "schat", { name, text: clipped, at: now } satisfies SpectatorChatEntry);
      return;
    }
    const matched = findProfanity(clipped);
    const text = matched.length ? censorText(clipped) : clipped;
    if (matched.length) {
      const db = await this.db();
      if (db) {
        try {
          await db
            .prepare(
              `INSERT INTO chat_flags (id, match_id, user_id, username, color, text, matched_words, created_at)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
            )
            .bind(crypto.randomUUID(), match.id, session.userId ?? null, name, "s", clipped, matched.join(","), now)
            .run();
        } catch (err) {
          console.error("failed to record chat flag", match.id, err);
        }
      }
    }
    const entry: SpectatorChatEntry = { name, text, at: now };
    match.spectatorChat = [...(match.spectatorChat ?? []), entry].slice(-50);
    await this.saveMatch(match, false);
    this.sendWatchers(match, "schat", entry);
  }

  // ---------------- voluntary rule reveal ----------------

  // A player may show their secret rule to the table mid-game. Irreversible;
  // the opponent and all spectators learn it immediately, and reconnects
  // replay it via the start payload.
  private async revealRule(ws: WebSocket) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before revealing your rule.");
    if (!match.startedAt) return error(ws, "not_started", "The game has not started yet.");
    if (match.revealed?.[session.color]) return;

    match.revealed = { ...(match.revealed ?? {}), [session.color]: true };
    await this.saveMatch(match, false);
    const nerfId = session.color === "w" ? match.setup.whiteNerfId : match.setup.blackNerfId;
    const payload = { color: session.color, nerfId };
    this.broadcast(match, "reveal", payload);
    this.sendWatchers(match, "reveal", payload);
  }

  // ---------------- draft mode (buff drafts) ----------------

  // The single place that decides what each receiver may see of the draft
  // state. Visibility rules:
  // - Held buff IDENTITIES are hidden like nerfs: a seat sees its own cards,
  //   but the opponent's held buffs arrive masked ({ hidden, tier, spent,
  //   nullified }) unless the match has picksVisible or the card's identity
  //   already showed on the table (instant effect, activation, or a granted
  //   move; see draftRebuild). Everything reveals at game end.
  // - Board effects, tempo counters, and the draft counters are public.
  // - A pending offer's cards are visible to the offer's own seat, plus the
  //   opposing seat when the match was created with picksVisible. Without
  //   picksVisible the opposing seat only learns that an offer is pending.
  // - Draft flags and the one-shot oppReveal snapshot are per-seat secrets;
  //   the opposing seat gets flags only under picksVisible, never the reveal.
  // - Spectators get none of the hidden data: no offers, no pending markers,
  //   no flags, no reveals, and BOTH sides' held buffs masked, regardless of
  //   settings.
  // - The draft RNG state is never serialized for anyone: it would let a
  //   client predict every future offer.
  private maskBuff(inst: BuffInstance) {
    return {
      hidden: true as const,
      tier: inst.tier as number,
      ...(inst.spent ? { spent: true } : {}),
      ...(inst.nullified ? { nullified: true } : {}),
    };
  }

  private draftStateFor(game: NerfGame, match: StoredMatch, seat: Color | "spectator") {
    const bs = game.buffs;
    if (!bs) return null;
    const playerState = (color: Color) => {
      const ps = bs.players[color];
      const self = seat === color;
      const open = self || (seat !== "spectator" && !!match.picksVisible);
      return {
        buffs: open ? ps.buffs : ps.buffs.map((b) => (this.isBuffRevealed(b) ? b : this.maskBuff(b))),
        draftsTaken: ps.draftsTaken,
        nextDraftAt: ps.nextDraftAt,
        offer: open ? ps.offer : null,
        ...(seat !== "spectator" && !open && ps.offer ? { offerPending: true } : {}),
        ...(open ? { flags: ps.flags } : {}),
        ...(self ? { oppReveal: ps.oppReveal ?? null } : {}),
        ...(ps.nerfRemoved ? { nerfRemoved: true } : {}),
        revived: ps.revived,
      };
    };
    return {
      cadence: bs.cadence,
      effects: bs.effects,
      extraMoves: bs.extraMoves,
      skips: bs.skips,
      ...(bs.chainKingGuard ? { chainKingGuard: bs.chainKingGuard } : {}),
      ...(bs.historyDiverged ? { historyDiverged: true } : {}),
      players: { w: playerState("w"), b: playerState("b") },
    };
  }

  private sendDraftState(match: StoredMatch, game: NerfGame) {
    for (const color of ["w", "b"] as Color[]) {
      const seatWs = this.connectedSession(match.id, color);
      if (!seatWs) continue;
      const state = this.draftStateFor(game, match, color);
      if (state) send(seatWs, "dtState", { state });
    }
  }

  // Spectators keep an engine replica too, so identity reveals (a hidden
  // passive's granted move) must reach them the same way, spectator-filtered.
  private sendWatcherDraftState(match: StoredMatch, game: NerfGame) {
    const state = this.draftStateFor(game, match, "spectator");
    if (state) this.sendWatchers(match, "dtState", { state });
  }

  // The draft record a given viewer may replay: your own picked cards are
  // yours to see, the opponent's picks are masked to { hidden, tier } until
  // the card's identity showed on the table (instant effect, activation, or
  // a granted move), a bank only reveals that it happened, and buff
  // activations carry their targets (the effects are on the board anyway).
  // Spectators get both sides masked the same way. The pick's offer slot
  // index stays private with the rest of the offer.
  private publicDraftActions(match: StoredMatch, viewer: Color | "spectator") {
    const rebuild = this.draftRebuild?.matchId === match.id ? this.draftRebuild : null;
    return (match.draftActions ?? []).map((action, i) => {
      if (action.a !== "pick") return action;
      const open = !!match.picksVisible || viewer === action.color;
      const acquired = rebuild?.acquired.get(i);
      const cards = action.cards.map((card, j) => {
        const inst = acquired?.[j];
        const revealed =
          open || BUFF_BY_ID[card.id]?.kind === "instant" || (inst ? this.isBuffRevealed(inst) : false);
        return revealed ? card : { hidden: true as const, tier: card.tier };
      });
      return { ply: action.ply, color: action.color, a: "pick" as const, cards };
    });
  }

  // Shared validation for the draft frames: a seated, live, started draft
  // match rebuilt through the engine.
  private async draftContext(
    ws: WebSocket,
  ): Promise<{ session: SessionAttachment; match: StoredMatch; game: NerfGame } | null> {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) {
      error(ws, "no_game", "Join a game before drafting.");
      return null;
    }
    if (!match.draft) {
      error(ws, "not_draft", "This game is not a Draft game.");
      return null;
    }
    if (await this.finishOnFlag(match)) return null;
    if (match.result) {
      error(ws, "game_over", "This game is over.");
      return null;
    }
    // Buff frames wait for the opening nerf draft like moves do.
    if (match.nerfOptions && !match.startedAt) {
      error(ws, "nerf_pending", "Pick your nerf before the game starts.");
      return null;
    }
    const game = await this.gameForPlay(match);
    if (!game?.buffs) {
      if (!match.result) error(ws, "no_game", "The game has not started yet.");
      return null;
    }
    return { session, match, game };
  }

  // Persist a resolved draft action, tell everyone the public outcome, and
  // re-sync both seats' filtered state. The pick event is public but the
  // picked card's identity is not: the picker gets the real cards, everyone
  // else gets masked entries (tier only) unless picksVisible or the card is
  // an instant (its effect is on the board, so replicas must replay it).
  // A use always carries the card identity: the effect must replay on every
  // replica, and a fired card's face is public knowledge anyway. Instant and
  // activated buffs can end the game on the spot (a removal or freeze can
  // decide it), so the end flow runs here too.
  private async settleDraftAction(
    match: StoredMatch,
    game: NerfGame,
    resolved: {
      color: Color;
      kind: "picked" | "banked";
      cards?: { id: string; tier: number }[];
      acquired?: BuffInstance[];
    } | null,
    used?: { color: Color; buffIndex: number; picks: BuffPick[]; card?: { id: string; tier: number } },
  ) {
    if (game.result && !match.result) {
      const now = Date.now();
      match.clocks = this.currentClocks(match, now);
      match.runningSince = null;
      match.result = game.result;
      match.completedAt = now;
    } else if (!match.result && game.board.turn !== this.activeColor(match)) {
      // A buff use consumed the activator's turn: bank their elapsed time
      // and start charging the new mover, exactly like a played move.
      const now = Date.now();
      match.clocks = this.currentClocks(match, now);
      if (match.runningSince !== null) match.runningSince = now;
      match.turnColor = game.board.turn;
    }
    // Resume the paused clock once no offer is pending on either side, or
    // once the free lock-in window has already expired (the clock only stays
    // paused during the window itself).
    const bs = game.buffs;
    const offersPending = !!bs?.players.w.offer || !!bs?.players.b.offer;
    if (!offersPending) match.dtDeadline = null;
    if (
      (!offersPending || !match.dtDeadline) &&
      match.startedAt &&
      !match.result &&
      match.runningSince === null
    ) {
      match.runningSince = Date.now();
    }
    // House seats: a resolved action can hand the turn (or a fresh offer) to
    // the house side. No-op for purely human games.
    this.armBotAction(match, game, Date.now());
    await this.saveMatch(match);
    if (resolved) {
      const publicFrame = { color: resolved.color, kind: resolved.kind };
      const ownFrame = resolved.cards ? { ...publicFrame, cards: resolved.cards } : publicFrame;
      const maskedCards = resolved.acquired?.map((b) =>
        this.isBuffRevealed(b) ? { id: b.id, tier: b.tier as number } : this.maskBuff(b),
      );
      const maskedFrame = maskedCards ? { ...publicFrame, cards: maskedCards } : publicFrame;
      const oppColor: Color = resolved.color === "w" ? "b" : "w";
      send(this.connectedSession(match.id, resolved.color), "dtResolved", ownFrame);
      send(
        this.connectedSession(match.id, oppColor),
        "dtResolved",
        match.picksVisible ? ownFrame : maskedFrame,
      );
      this.sendWatchers(match, "dtResolved", maskedFrame);
    }
    if (used) {
      this.broadcast(match, "dtUsed", used);
      this.sendWatchers(match, "dtUsed", used);
    }
    this.sendDraftState(match, game);
    this.sendWatcherDraftState(match, game);
    if (match.result) await this.endMatch(match);
  }

  // Resolve a seat's pending offer by picking a card. Shared by the socket
  // frame handler and the lock-in deadline auto-resolver.
  private async resolveDraftPick(match: StoredMatch, game: NerfGame, color: Color, index: number) {
    const bs = game.buffs!;
    const ps = bs.players[color];
    const before = ps.buffs.length;
    const effectsBefore = bs.effects.length;
    const mutationsBefore = bs.mutations ?? 0;
    pickDraftCard(game, color, index);
    // Everything acquired by this pick (take-both drafts can grab several
    // cards) is recorded; identity reaches the opponent masked unless the
    // card reveals itself (see settleDraftAction).
    const acquired = ps.buffs.slice(before);
    // A pick whose init observably touched the board or effects is public
    // like an instant's effect: replicas must replay it or they desync.
    // Mirrored by applyStoredDraftAction so rebuilds re-derive the same set.
    if (bs.effects.length !== effectsBefore || (bs.mutations ?? 0) !== mutationsBefore) {
      for (const b of acquired) this.markBuffRevealed(b);
    }
    if (this.draftRebuild?.matchId === match.id) {
      this.draftRebuild.acquired.set(match.draftActions?.length ?? 0, acquired);
    }
    const cards = acquired.map((b) => ({ id: b.id, tier: b.tier as number }));
    match.draftActions = [
      ...(match.draftActions ?? []),
      { ply: match.moves.length, color, a: "pick", index, cards },
    ];
    await this.settleDraftAction(match, game, { color, kind: "picked", cards, acquired });
  }

  private async resolveDraftBank(match: StoredMatch, game: NerfGame, color: Color) {
    bankDraft(game, color);
    match.draftActions = [...(match.draftActions ?? []), { ply: match.moves.length, color, a: "bank" }];
    await this.settleDraftAction(match, game, { color, kind: "banked" });
  }

  private async draftPick(ws: WebSocket, data: unknown) {
    const ctx = await this.draftContext(ws);
    if (!ctx) return;
    const { session, match, game } = ctx;
    const color = session.color!;
    const ps = game.buffs!.players[color];
    const offer = ps.offer;
    if (!offer) return error(ws, "no_offer", "You have no pending buff draft.");
    const request = (data || {}) as { index?: unknown };
    const index = Number(request.index);
    if (!Number.isInteger(index) || !offer.cards[index]) {
      return error(ws, "bad_pick", "That card is not part of your offer.");
    }
    await this.resolveDraftPick(match, game, color, index);
  }

  private async draftBank(ws: WebSocket) {
    const ctx = await this.draftContext(ws);
    if (!ctx) return;
    const { session, match, game } = ctx;
    const color = session.color!;
    if (!game.buffs!.players[color].offer) {
      return error(ws, "no_offer", "You have no pending buff draft.");
    }
    await this.resolveDraftBank(match, game, color);
  }

  private async draftUse(ws: WebSocket, data: unknown) {
    const ctx = await this.draftContext(ws);
    if (!ctx) return;
    const { session, match, game } = ctx;
    const color = session.color!;
    const ps = game.buffs!.players[color];
    if (ps.offer) return error(ws, "draft_pending", "Resolve your buff draft first.");
    if (game.board.turn !== color) return error(ws, "not_your_turn", "Buffs activate on your turn.");
    const request = (data || {}) as { buffIndex?: unknown; picks?: unknown };
    const buffIndex = Number(request.buffIndex);
    if (!Number.isInteger(buffIndex) || !ps.buffs[buffIndex]) {
      return error(ws, "bad_buff", "You do not hold that buff.");
    }
    const picks = this.parseBuffPicks(request.picks);
    if (!picks || !this.buffPicksComplete(game, color, buffIndex, picks)) {
      return error(ws, "bad_target", "Those targets are not valid for that buff.");
    }
    const inst = ps.buffs[buffIndex];
    const theirs = game.buffs!.players[color === "w" ? "b" : "w"];
    const mineBefore = ps.buffs.length;
    const theirsBefore = theirs.buffs.length;
    if (!activateBuff(game, color, buffIndex, picks)) {
      return error(ws, "bad_buff", "That buff cannot be used right now.");
    }
    // Using a card makes it public, along with anything the use created or
    // moved between the players (Mirror copies, stolen cards).
    this.markBuffRevealed(inst);
    for (const added of ps.buffs.slice(mineBefore)) this.markBuffRevealed(added);
    for (const added of theirs.buffs.slice(theirsBefore)) this.markBuffRevealed(added);
    match.draftActions = [
      ...(match.draftActions ?? []),
      { ply: match.moves.length, color, a: "use", buffIndex, picks },
    ];
    await this.settleDraftAction(match, game, null, {
      color,
      buffIndex,
      picks,
      card: { id: inst.id, tier: inst.tier as number },
    });
  }

  private async draftTarget(ws: WebSocket, data: unknown) {
    const ctx = await this.draftContext(ws);
    if (!ctx) return;
    const { session, game } = ctx;
    const color = session.color!;
    const request = (data || {}) as { buffIndex?: unknown; picks?: unknown };
    const buffIndex = Number(request.buffIndex);
    if (!Number.isInteger(buffIndex) || !game.buffs!.players[color].buffs[buffIndex]) {
      return error(ws, "bad_buff", "You do not hold that buff.");
    }
    const picks = this.parseBuffPicks(request.picks);
    const collected = picks ? this.walkBuffPicks(game, color, buffIndex, picks) : null;
    if (!collected) return error(ws, "bad_target", "Those targets are not valid for that buff.");
    send(ws, "dtTargetReq", { buffIndex, target: buffNextTarget(game, color, buffIndex, collected) });
  }

  // ---------------- draft mode (opening nerf draft) ----------------

  // Deal the opening nerf draft for a Draft match. Difficulty is always
  // identical for the two seats: one tier pair is rolled for the whole deal
  // (an anchor tier plus a partner tier within one of it, possibly the same
  // tier), and BOTH seats get one card of the anchor tier and one card of
  // the partner tier. All four cards are distinct. The deal comes from the
  // match seed RNG so a Durable Object restart re-deals the same options
  // (never Math.random).
  private dealNerfDraftOptions(match: StoredMatch): Record<Color, string[]> {
    const master = new RNG(match.setup.seed);
    master.fork(); // skip: white's nerf seed, already derived in startPayload
    master.fork(); // skip: black's nerf seed
    const rng = master.fork();

    // The deal draws from the capped opening pool (see MAX_OPENING_NERF_TIER
    // in the nerf library), minus any moderator-disabled nerfs
    // (card_overrides; beginNerfDraft warms the cached snapshot first). When
    // the disable list leaves no feasible tier pairing, the unfiltered pool
    // deals instead: a playable deal beats honoring the filter.
    const off = new Set(this.cardOverridesCache?.value.nerfOff ?? []);
    let pool: Nerf[] = openingNerfPool().filter((nerf) => !off.has(nerf.id));
    const ofTier = (tier: number) => pool.filter((nerf) => nerf.tier === tier);
    const takeOne = (tier: number, taken: Set<string>): string => {
      const candidates = ofTier(tier).filter((nerf) => !taken.has(nerf.id));
      const card = candidates[rng.int(candidates.length)];
      taken.add(card.id);
      return card.id;
    };
    // A tier pairing is feasible only if the pool supplies the four distinct
    // cards: four of the anchor tier when the partner tier matches it,
    // otherwise two of each.
    const feasible = (anchor: number, partner: number) =>
      partner === anchor
        ? ofTier(anchor).length >= 4
        : ofTier(anchor).length >= 2 && ofTier(partner).length >= 2;
    const tiersOf = () => [...new Set(pool.map((nerf) => nerf.tier))];
    const anchorsOf = (candidates: number[]) =>
      candidates.filter((anchor) =>
        candidates.some((partner) => Math.abs(partner - anchor) <= 1 && feasible(anchor, partner)),
      );
    let tiers = tiersOf();
    let anchorTiers = anchorsOf(tiers);
    if (anchorTiers.length === 0) {
      pool = openingNerfPool();
      tiers = tiersOf();
      anchorTiers = anchorsOf(tiers);
    }
    const anchorTier = anchorTiers[rng.int(anchorTiers.length)];
    const partnerTiers = tiers.filter(
      (partner) => Math.abs(partner - anchorTier) <= 1 && feasible(anchorTier, partner),
    );
    const partnerTier = partnerTiers[rng.int(partnerTiers.length)];
    const taken = new Set<string>();
    const first = [takeOne(anchorTier, taken), takeOne(partnerTier, taken)];
    const second = [takeOne(anchorTier, taken), takeOne(partnerTier, taken)];
    // Randomize each seat's card order and which seat gets which hand, so
    // neither the anchor card nor a specific hand always lands on one side.
    if (rng.int(2) === 1) first.reverse();
    if (rng.int(2) === 1) second.reverse();
    return rng.int(2) === 0 ? { w: first, b: second } : { w: second, b: first };
  }

  // Both seats of a Draft match are present: deal the opening nerf draft
  // instead of starting the game. The match stays un-started (clocks off,
  // moves and buff frames rejected with nerf_pending) until both picks land.
  private async beginNerfDraft(match: StoredMatch) {
    if (!match.nerfOptions) {
      // Warm the card-overrides snapshot so the (synchronous) deal below can
      // read the disabled-nerf list from the cache. The dealt options are
      // persisted, so a later snapshot refresh can never re-deal them.
      await this.cardOverridesSnapshot();
      match.nerfOptions = this.dealNerfDraftOptions(match);
      // 15 second lock-in: the pick auto-resolves at the deadline so a
      // stalling (or vanished) player cannot hold the table hostage.
      match.nerfDeadline = Date.now() + draftLockInMs;
    }
    // House seats pick their nerf after a human-like beat (2-8s), well
    // inside the lock-in window.
    this.armBotAction(match, null, Date.now());
    await this.saveMatch(match);
    this.sendStart(match, "w");
    this.sendStart(match, "b");
  }

  private async nerfDraftPick(ws: WebSocket, data: unknown) {
    const session = this.session(ws);
    const match = session.matchId ? await this.loadMatch(session.matchId) : null;
    if (!match || !session.color) return error(ws, "no_game", "Join a game before drafting.");
    if (!match.draft) return error(ws, "not_draft", "This game is not a Draft game.");
    if (match.result) return error(ws, "game_over", "This game is over.");
    if (!match.nerfOptions || match.startedAt) {
      return error(ws, "no_nerf_draft", "There is no nerf draft to pick from.");
    }
    const color = session.color;
    if (match.nerfPicks?.[color] != null) {
      return error(ws, "already_picked", "You already picked your nerf.");
    }
    // Index-only validation: clients choose between the two server-dealt
    // options and can never smuggle in a nerf id of their own.
    const index = Number((data as { index?: unknown } | undefined)?.index);
    if (index !== 0 && index !== 1) {
      return error(ws, "bad_pick", "That card is not part of your options.");
    }

    match.nerfPicks = { ...(match.nerfPicks ?? {}), [color]: index };
    const opp: Color = color === "w" ? "b" : "w";
    const oppPick = match.nerfPicks[opp];
    if (oppPick == null) {
      await this.saveMatch(match);
      // Progress only: both seats learn that this side picked, never which
      // card. Spectators learn nothing.
      this.broadcast(match, "dtNerfPicked", { color });
      return;
    }

    await this.finalizeNerfDraft(match);
  }

  // Both picks are in: lock the chosen rules and start the game proper.
  // Clocks only begin now, so neither side paid for choosing.
  private async finalizeNerfDraft(match: StoredMatch) {
    match.setup.whiteNerfId = match.nerfOptions!.w[match.nerfPicks!.w!];
    match.setup.blackNerfId = match.nerfOptions!.b[match.nerfPicks!.b!];
    // Visible-picks matches: both chosen rules are open from move one,
    // through the same reveal channel voluntary reveals use.
    if (match.picksVisible) match.revealed = { w: true, b: true };
    match.nerfDeadline = null;
    match.startedAt = Date.now();
    // The draft can finalize from the alarm (a house pick landing, or the
    // 15s lock-in auto-resolve) while a human seat is disconnected — during the
    // draft the game was not started, so detachSession could not pause the
    // clock. Start PAUSED in that case so the human's clock does not burn on a
    // board the guard-held bot cannot advance; reconnectMatch's house-resume
    // block resumes it and re-arms the bot when they return. A present human
    // (the normal accept) is byte-for-byte unchanged: runningSince = startedAt.
    const humanGone = (["w", "b"] as Color[]).some(
      (color) => !match.bots?.[color] && match.disconnectedAt[color] && !this.connectedSession(match.id, color),
    );
    match.runningSince = humanGone ? null : match.startedAt;
    // House seats: the game just started, so white's first move may be a
    // house action.
    match.botActAt = null;
    this.armBotAction(match, null, match.startedAt);
    await this.saveMatch(match);
    this.sendStart(match, "w");
    this.sendStart(match, "b");
  }

  // Lock-in deadline enforcement, run from the alarm. Overdue nerf picks
  // take the first option (the game cannot start without them). Overdue
  // buff offers are NOT auto-resolved anymore: the offer stays open, the
  // clock resumes, and the straggler pays for further deliberation with
  // their own time — their client shows the pick in a side panel.
  private async enforceDraftDeadlines(match: StoredMatch, now: number): Promise<boolean> {
    if (!match.draft || match.result) return false;
    if (match.nerfOptions && !match.startedAt) {
      if (!match.nerfDeadline || now < match.nerfDeadline + draftPickGraceMs) return false;
      match.nerfPicks = { ...(match.nerfPicks ?? {}) };
      for (const color of ["w", "b"] as Color[]) {
        if (match.nerfPicks[color] == null) match.nerfPicks[color] = 0;
      }
      await this.finalizeNerfDraft(match);
      return true;
    }
    if (!match.startedAt || !match.dtDeadline || now < match.dtDeadline) return false;
    match.dtDeadline = null;
    if (!match.result && match.runningSince === null) match.runningSince = now;
    await this.saveMatch(match, false);
    return true;
  }

  private parseBuffPicks(raw: unknown): BuffPick[] | null {
    if (raw === undefined) return [];
    // 32 bounds server work while leaving room for the longest pick chains
    // (Total Warp moves up to 15 pieces via alternating piece / destination
    // picks; Warp Sovereign runs up to 6).
    if (!Array.isArray(raw) || raw.length > 32) return null;
    const picks: BuffPick[] = [];
    for (const entry of raw) {
      const pick = (entry || {}) as { square?: unknown; buffIndex?: unknown };
      const next: BuffPick = {};
      if (Number.isInteger(pick.square)) next.square = Number(pick.square);
      if (Number.isInteger(pick.buffIndex)) next.buffIndex = Number(pick.buffIndex);
      if (next.square === undefined && next.buffIndex === undefined) return null;
      picks.push(next);
    }
    return picks;
  }

  // Walk the buff's own target chain: every pick must be one of the engine's
  // offered candidates. This keeps a client from smuggling arbitrary squares
  // or buff indexes into an effect.
  private walkBuffPicks(game: NerfGame, color: Color, buffIndex: number, picks: BuffPick[]): BuffPick[] | null {
    const collected: BuffPick[] = [];
    for (const pick of picks) {
      const target = buffNextTarget(game, color, buffIndex, collected);
      if (!target) return null;
      if (target.kind === "square") {
        if (pick.square === undefined || !target.squares.includes(pick.square)) return null;
        collected.push({ square: pick.square });
      } else {
        if (pick.buffIndex === undefined || !target.options.some((option) => option.index === pick.buffIndex)) {
          return null;
        }
        collected.push({ buffIndex: pick.buffIndex });
      }
    }
    return collected;
  }

  private buffPicksComplete(game: NerfGame, color: Color, buffIndex: number, picks: BuffPick[]): boolean {
    const collected = this.walkBuffPicks(game, color, buffIndex, picks);
    if (!collected) return false;
    const next = buffNextTarget(game, color, buffIndex, collected);
    // A finishable step means the picks so far already form a complete
    // effect (Warp Sovereign's "stop after any pair"), so an early stop is
    // as valid as walking the whole chain.
    return next === null || (next.kind === "square" && !!next.finishable);
  }

  // ---------------- spectating & lobby ----------------

  private async watchMatch(ws: WebSocket, data: unknown) {
    const session = this.session(ws);
    if (session.matchId) return error(ws, "already_joined", "This connection already belongs to a game.");
    const id = String((data as { id?: unknown } | undefined)?.id || "").trim().toUpperCase();

    // Arena (external) game (Tier 2 / M3): spectate via the replica if the arena
    // is already streaming it; otherwise register the watch and wait — the next
    // /arena/games sync puts this id in the watch set, the arena pushes a started
    // snapshot, and ingestExternalSnapshot flushes the wstart to this socket.
    if (this.externalGames.has(id) || this.externalMatches.has(id)) {
      const next = { ...session, watching: id };
      this.sessions.set(ws, next);
      ws.serializeAttachment(next);
      const replica = this.externalMatches.get(id);
      if (replica) this.sendWstart(ws, replica);
      this.broadcastWatchers(id);
      return;
    }

    const match = await this.loadMatch(id);
    if (!match) return error(ws, "not_found", "No live game with that id.");
    await this.finishOnFlag(match);

    const next = { ...session, watching: id };
    this.sessions.set(ws, next);
    ws.serializeAttachment(next);

    this.sendWstart(ws, match);
    this.broadcastWatchers(id);
  }

  private watchLeave(ws: WebSocket) {
    const session = this.session(ws);
    if (!session.watching) return;
    const id = session.watching;
    const next = { ...session };
    delete next.watching;
    this.sessions.set(ws, next);
    ws.serializeAttachment(next);
    this.broadcastWatchers(id);
    this.dropExternalIfUnwatched(id);
  }

  // Drop a watched arena game's replica once its last spectator leaves — the
  // arena stops streaming it (it drops out of the watch set), so keeping the
  // replica would only let it go stale. A later re-watch rebuilds it from a
  // fresh snapshot.
  private dropExternalIfUnwatched(id: string) {
    if (this.externalMatches.has(id) && this.watcherCount(id) === 0) this.externalMatches.delete(id);
  }

  // One snapshot for the lobby page: who is online right now and which games
  // can be watched. Polled by the client every few seconds.
  private async lobbySnapshot(ws: WebSocket) {
    const now = Date.now();
    // Serve the shared snapshot from cache when it is fresh. This skips the
    // full match scan and every other await on the hot path (flag checks, the
    // D1 rating lookup) for the burst of concurrent polls that land inside the
    // TTL window. The snapshot is public and identical for every viewer, so a
    // shared copy leaks no per-viewer private data.
    if (this.lobbyCache && now - this.lobbyCache.at < GameServer.LOBBY_CACHE_TTL_MS) {
      return send(ws, "lobby", this.lobbyCache.payload);
    }
    // Live matches only. The lobby only ever lists unfinished games (open
    // challenges and in-progress games); finished records were filtered out
    // below anyway. Reading them via the index avoids a full-table scan on
    // every lobby poll, the most frequent human-driven path into the DO.
    const matches = await this.loadLiveMatches();

    const liveGames: Array<{
      id: string;
      players: ReturnType<GameServer["playersPayload"]>;
      rated: boolean;
      draft: boolean;
      mode?: DraftMode;
      timeSec: number;
      incrementSec: number;
      moves: number;
      watchers: number;
    }> = [];
    const playingUserIds = new Set<string>();
    // Friend games waiting for an opponent, shown in the lobby as open
    // challenges anyone can accept. Matchmade (autoStart) games waiting for
    // their paired players to arrive are not challenges.
    const challenges: Array<{
      id: string;
      host: { name: string; rating: number | null };
      rated: boolean;
      draft: boolean;
      mode?: DraftMode;
      timeSec: number;
      incrementSec: number;
      createdAt: number;
    }> = [];
    for (const match of matches) {
      // A dealt nerf draft means both seats are taken: not a challenge.
      if (!match.startedAt && !match.result && !match.autoStart && !match.nerfOptions) {
        // Only list codes whose host is still connected; otherwise the code
        // is a dead end for whoever clicks it. Direct challenges are reserved
        // for their invitee and never appear as open challenges.
        if (!match.invitedUsername && this.connectedSession(match.id, "w")) {
          const host = match.users?.w;
          challenges.push({
            id: match.id,
            host: host ? { name: host.name, rating: Math.round(host.rating) } : { name: "Anonymous", rating: null },
            rated: !!match.rated,
            draft: !!match.draft,
            ...(match.mode ? { mode: match.mode } : {}),
            timeSec: match.setup.timeSec,
            incrementSec: match.setup.incrementSec,
            createdAt: match.createdAt,
          });
        }
        continue;
      }
      if (!match.startedAt || match.result) continue;
      await this.finishOnFlag(match, now, false);
      if (match.result) continue;
      for (const color of ["w", "b"] as Color[]) {
        const id = match.users?.[color]?.id;
        if (id) playingUserIds.add(id);
      }
      liveGames.push({
        id: match.id,
        players: this.playersPayload(match),
        rated: !!match.rated,
        draft: !!match.draft,
        ...(match.mode ? { mode: match.mode } : {}),
        timeSec: match.setup.timeSec,
        incrementSec: match.setup.incrementSec,
        moves: match.moves.length,
        watchers: this.watcherCount(match.id),
      });
    }
    // Bot-vs-bot games simulated on the OCI arena (Tier 2 / M2) show alongside
    // real live games. Gated by ARENA_LOBBY_ENABLED; empty when off.
    for (const g of this.externalLiveGames(now)) liveGames.push(g);
    liveGames.sort((a, b) => b.watchers - a.watchers || b.moves - a.moves);
    challenges.sort((a, b) => b.createdAt - a.createdAt);

    // Who is queued for quick pairing right now. Each connected entry is also
    // surfaced as a joinable seek, so a player browsing the lobby can see and
    // answer someone waiting in a different pool instead of both idling.
    const queuedUserIds = new Set<string>();
    const seeks: Array<{
      pool: string;
      name: string;
      rating: number | null;
      mode: DraftMode;
      timeSec: number;
      incrementSec: number;
      at: number;
      // Stable identity so the client can answer a specific seek and the server
      // can pair with exactly that person (or bot), never a random pool waiter.
      userId: string;
      house: boolean;
    }> = [];
    for (const mode of QUEUE_MODES) {
      for (const [poolName, pool] of Object.entries(QUEUE_POOLS)) {
        const entries = (await this.ctx.storage.get<QueueEntry[]>(this.queueKey(mode, poolName))) ?? [];
        for (const entry of entries) {
          if (!this.socketForAttachment(entry.attachmentId)) continue;
          queuedUserIds.add(entry.userId);
          seeks.push({
            pool: poolName,
            name: entry.username,
            // The seeker's rating in this pool's mode bucket.
            rating: Math.round(entry.rating),
            mode,
            timeSec: pool.timeSec,
            incrementSec: pool.incrementSec,
            at: entry.at,
            userId: entry.userId,
            house: false,
          });
        }
      }
    }
    // House players seeking in a pool surface exactly like human seeks. Their
    // rows come from DO storage (no D1), and failures here degrade to "no
    // house seeks" without touching the human lobby.
    let houseSeeks: HouseSeekEntry[] = [];
    try {
      houseSeeks = (await this.ctx.storage.get<HouseSeekEntry[]>(houseSeeksKey)) ?? [];
      for (const seek of houseSeeks) {
        const pool = QUEUE_POOLS[seek.pool];
        if (!pool) continue;
        queuedUserIds.add(seek.userId);
        seeks.push({
          pool: seek.pool,
          name: seek.name,
          rating: Math.round(seek.rating),
          mode: seek.mode,
          timeSec: pool.timeSec,
          incrementSec: pool.incrementSec,
          at: seek.at,
          userId: seek.userId,
          house: true,
        });
      }
    } catch {
      houseSeeks = [];
    }
    seeks.sort((a, b) => a.at - b.at);

    // Every signed-in account with an open socket, deduped; anonymous sockets
    // are only counted.
    const seen = new Map<string, { name: string; rating: number | null; status: string; avatar: string | null }>();
    let anonymous = 0;
    for (const [socket, session] of this.sessions) {
      if (socket.readyState !== WebSocket.OPEN) continue;
      if (!session.userId || !session.username) {
        anonymous++;
        continue;
      }
      const status = playingUserIds.has(session.userId)
        ? "playing"
        : queuedUserIds.has(session.userId)
        ? "searching"
        : "online";
      const existing = seen.get(session.userId);
      // "playing" wins over "searching" wins over "online" across tabs.
      if (!existing || existing.status === "online" || (existing.status === "searching" && status === "playing")) {
        seen.set(session.userId, { name: session.username, rating: null, status, avatar: null });
      }
    }

    // House players appear in the online list too: seeking ones from the
    // seek rows. Ratings and avatars come from what is already in hand (seek
    // entries and match seats), so this adds no D1 work.
    try {
      for (const seek of houseSeeks) {
        if (!seen.has(seek.userId)) {
          seen.set(seek.userId, {
            name: seek.name,
            rating: Math.round(seek.rating),
            status: "searching",
            avatar: seek.avatar,
          });
        }
      }
      // EVERY seat of a live match counts as online-and-playing: humans too,
      // not just house bots. A player mid-game may have no identified lobby
      // socket at all (their game socket is a separate session), which used
      // to drop them from the online list entirely while they played.
      for (const match of matches) {
        if (!match.startedAt || match.result) continue;
        for (const color of ["w", "b"] as Color[]) {
          const user = match.users?.[color];
          if (!user) continue;
          const existing = seen.get(user.id);
          if (!existing) {
            seen.set(user.id, {
              name: user.name,
              rating: Math.round(user.rating),
              status: "playing",
              avatar: user.avatar ?? null,
            });
          } else if (existing.status !== "playing") {
            existing.status = "playing";
          }
        }
      }
    } catch {}

    // Attach ratings for the online list in one query.
    const db = await this.db();
    if (db && seen.size > 0) {
      try {
        const ids = [...seen.keys()];
        const placeholders = ids.map(() => "?").join(",");
        const rows = await db
          .prepare(`SELECT id, username, rating, avatar FROM users WHERE id IN (${placeholders})`)
          .bind(...ids)
          .all<{ id: string; username: string; rating: number; avatar: string | null }>();
        for (const row of rows.results) {
          const entry = seen.get(row.id);
          if (entry) {
            entry.rating = Math.round(row.rating);
            entry.avatar = row.avatar;
          }
        }
      } catch {}
    }

    const players = [...seen.values()]
      .sort((a, b) => (b.rating ?? 0) - (a.rating ?? 0))
      .slice(0, 50);
    const payload = {
      players,
      anonymous,
      games: liveGames.slice(0, 25),
      challenges: challenges.slice(0, 25),
      seeks: seeks.slice(0, 25),
    };
    // Refresh the shared cache so the rest of this poll burst is served without
    // rescanning. Set last, after any finishOnFlag writes above, so the cached
    // copy reflects the freshest state.
    this.lobbyCache = { at: now, payload };
    send(ws, "lobby", payload);
  }

  private async sendClocks(ws: WebSocket) {
    const session = this.session(ws);
    const watchedId = session.matchId ?? session.watching;
    const match = watchedId ? await this.loadMatch(watchedId) : null;
    if (!match) return send(ws, "n");
    if (await this.finishOnFlag(match)) return;
    // Self-heal from the client heartbeat (~every 10s): re-arm this game's own
    // alarm so a pending house-bot move or a clock deadline keeps firing even if
    // the global alarm chain died between deadlines (e.g. an isolate eviction
    // mid-tick left no next alarm). This is what lets a stuck bot game recover
    // on its own instead of freezing until the player refreshes. Cheap: a
    // getAlarm read, and a setAlarm only when this game actually needs an
    // earlier alarm than the one already stored (so a no-op in steady state).
    if (!match.result) {
      try {
        await this.scheduleAlarmForMatch(match);
      } catch {}
    }
    const clocks = this.currentClocks(match);
    send(ws, "n", { wc: Math.round(clocks.w), bc: Math.round(clocks.b) });
  }

  private candidateAlarm(match: StoredMatch, now = Date.now()): number | null {
    const candidates: number[] = [];
    if (match.setup.timeSec && match.startedAt && !match.result && match.runningSince !== null) {
      const active = this.activeColor(match);
      const grace = this.movesByColor(match, active) === 0 ? firstMoveGraceMs : 0;
      candidates.push(match.runningSince + match.clocks[active] + grace);
    }
    // Draft lock-in deadlines: overdue picks auto-resolve from the alarm.
    if (!match.result) {
      if (match.nerfDeadline && match.nerfOptions && !match.startedAt) candidates.push(match.nerfDeadline + draftPickGraceMs);
      if (match.dtDeadline && match.startedAt) candidates.push(match.dtDeadline);
      // Pending house action (move or draft pick). An overdue timer clamps to
      // just past now so a missed alarm re-fires immediately instead of never —
      // UNLESS the bot is guard-held because the human seat is genuinely gone.
      // In that case houseTick will only skip it, so clamping to now+300 would
      // spin a ~3Hz alarm for the whole abandonment window (up to 30 min),
      // burning CPU on the single thread and helping tip it past its reset
      // limit. When guard-held, drop the pending-action candidate entirely: the
      // move re-arms the moment the human reconnects (reconnectMatch) or pings
      // (sendClocks), and the abandonment GC still fires via its own candidate.
      if (match.botActAt) {
        const guardHeld =
          !!match.startedAt &&
          !!match.bots &&
          (["w", "b"] as Color[]).some(
            (c) => !match.bots?.[c] && match.disconnectedAt[c] && !this.connectedSession(match.id, c),
          );
        if (!guardHeld) candidates.push(Math.max(match.botActAt, now + 300));
      }
    }
    for (const color of ["w", "b"] as Color[]) {
      const disconnectedAt = match.disconnectedAt[color];
      if (disconnectedAt && !match.opponentGoneNotified[color]) candidates.push(disconnectedAt + disconnectGraceMs);
    }
    const expiry = match.completedAt ?? match.createdAt;
    if (match.completedAt) candidates.push(expiry + finishedRetentionMs);
    else if (!match.startedAt) candidates.push(expiry + 30 * 60 * 1000);
    else if (this.connectedSessions(match.id).length === 0) {
      const latestDisconnect = Math.max(match.disconnectedAt.w ?? 0, match.disconnectedAt.b ?? 0);
      if (latestDisconnect) candidates.push(latestDisconnect + 30 * 60 * 1000);
    }

    const next = Math.min(...candidates.filter((candidate) => candidate > now));
    return Number.isFinite(next) ? next : null;
  }

  private async scheduleAlarmForMatch(match: StoredMatch) {
    const next = this.candidateAlarm(match);
    if (!next) return;
    const existing = await this.ctx.storage.getAlarm();
    if (!existing || next < existing) await this.ctx.storage.setAlarm(next);
  }

  private async scheduleNextAlarm(matches: StoredMatch[]) {
    const now = Date.now();
    // One corrupt match must not abort the whole reschedule (which would kill
    // the alarm chain): treat a candidate that throws as "no deadline".
    let next = Math.min(
      ...matches.map((match) => {
        try {
          return this.candidateAlarm(match) ?? Number.POSITIVE_INFINITY;
        } catch {
          return Number.POSITIVE_INFINITY;
        }
      }),
    );
    // Slow house heartbeat while any human socket is connected, so the house
    // roster keeps its queue presence fresh. With nobody online there is no
    // heartbeat: the DO goes idle until the next socket/save re-arms it via
    // scheduleAlarmForMatch (live house games still wake it per move).
    if (this.humanSocketCount() > 0) next = Math.min(next, now + houseHeartbeatMs);
    // No pending deadline means no alarm.
    if (!Number.isFinite(next)) return;
    let target = Math.max(next, now + 250);
    // Never push out an earlier still-future alarm someone armed mid-tick
    // (e.g. the house pickup's quick follow-up).
    const existing = await this.ctx.storage.getAlarm();
    if (existing && existing > now && existing < target) target = existing;
    await this.ctx.storage.setAlarm(target);
  }

  // Pull the stored alarm earlier when needed (never later).
  private async armAlarmBy(at: number) {
    const existing = await this.ctx.storage.getAlarm();
    if (!existing || at < existing) await this.ctx.storage.setAlarm(at);
  }

  private humanSocketCount(): number {
    let n = 0;
    for (const [ws] of this.sessions) {
      if (ws.readyState === WebSocket.OPEN) n++;
    }
    return n;
  }

  // Bounded GC sweep: walk the "match:" keyspace one page at a time (never the
  // whole table at once, which on a bloated table blows the DO CPU/storage limit
  // before it can delete anything). Deletes expired records and folds any live
  // ids it sees into the persisted index. Returns true if more pages remain, so
  // the caller can keep draining until the table is clean.
  private async sweepExpired(now = Date.now()): Promise<boolean> {
    const pageSize = 100;
    // start is inclusive; "match;" (';' is ':' + 1) bounds the "match:"
    // keyspace without touching other keys (queue:, house:, live:).
    const start = this.gcCursor ?? "match:";
    const page = await this.ctx.storage.list<StoredMatch>({ start, end: "match;", limit: pageSize });
    const entries = [...page.entries()];
    if (!entries.length) {
      this.gcCursor = null;
      return false;
    }
    await this.ensureLiveIndex();
    let indexChanged = false;
    for (const [key, match] of entries) {
      // The inclusive start re-lists the previous page's last key; skip it.
      if (key === this.gcCursor) continue;
      if (this.isExpired(match, now)) {
        await this.deleteMatch(match);
        indexChanged = true;
        continue;
      }
      if (!match.result && this.liveMatchIndex && !this.liveMatchIndex.has(match.id)) {
        this.liveMatchIndex.add(match.id);
        indexChanged = true;
      }
    }
    const more = entries.length === pageSize;
    this.gcCursor = more ? entries[entries.length - 1][0] : null;
    if (indexChanged) await this.persistLiveIndex();
    return more;
  }

  private isExpired(match: StoredMatch, now: number): boolean {
    if (match.completedAt && now - match.completedAt > finishedRetentionMs) return true;
    if (!match.startedAt && now - match.createdAt > 30 * 60 * 1000) return true;
    if (match.startedAt && this.connectedSessions(match.id).length === 0) {
      const latestDisconnect = Math.max(match.disconnectedAt.w ?? 0, match.disconnectedAt.b ?? 0);
      if (latestDisconnect && now - latestDisconnect > 30 * 60 * 1000) return true;
    }
    return false;
  }

  // /healthz revival hook: one bounded GC page. Cheap, and helps drain a bloated
  // table between alarms. Never a whole-table scan.
  private async cleanupExpired() {
    await this.sweepExpired();
  }

  private async maintenanceAll() {
    const now = Date.now();
    // Flag/deadline enforcement runs on live games only, read cheaply off the
    // persisted index (never a whole-table scan). Finished games need no
    // enforcement; the bounded sweep below is what removes them.
    const live = await this.loadLiveMatches();
    for (const match of live) {
      // One bad match (corrupt record, transient storage error) must not stop
      // flag enforcement for every other live game or break the alarm chain.
      try {
        await this.enforceDraftDeadlines(match, now);
        let changed = await this.finishOnFlag(match, now, false);
        for (const color of ["w", "b"] as Color[]) {
          const disconnectedAt = match.disconnectedAt[color];
          const opponent = this.connectedSession(match.id, color === "w" ? "b" : "w");
          if (disconnectedAt && opponent && !match.opponentGoneNotified[color] && now - disconnectedAt > disconnectGraceMs) {
            send(opponent, "opponentGone");
            match.opponentGoneNotified[color] = true;
            changed = true;
          }
        }
        if (this.isExpired(match, now)) {
          await this.deleteMatch(match);
          continue;
        }
        if (changed) await this.saveMatch(match, false);
      } catch (err) {
        console.error("maintenance failed for match", match.id, err);
      }
    }
    // Drain expired/finished records a bounded page at a time. Keep draining
    // fast (a quick follow-up alarm) until the table is clean, then fall back to
    // the normal per-move cadence.
    let more = false;
    try {
      more = await this.sweepExpired(now);
    } catch (err) {
      console.error("sweepExpired failed", err);
    }
    if (more) await this.armAlarmBy(Date.now() + 300);
    await this.scheduleNextAlarm(await this.loadLiveMatches());
  }
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (url.pathname === socketPath || url.pathname === "/healthz" || url.pathname.startsWith("/arena/")) {
      try {
        const id = env.GAME_SERVER.idFromName(globalServerName);
        return await env.GAME_SERVER.get(id).fetch(request);
      } catch (err) {
        // The game server threw. Without this the platform returns an opaque
        // 1101 page with no detail. Surface the actual error on /healthz so it
        // can be read from a browser (there is no other log access here), and
        // fail the socket upgrade cleanly instead of crashing the request.
        const message = err instanceof Error ? `${err.name}: ${err.message}` : String(err);
        const stack = err instanceof Error ? err.stack : undefined;
        console.error("game server fetch threw", err);
        if (url.pathname === "/healthz") {
          return Response.json({ ok: false, version: buildVersion, error: message, stack }, { status: 200 });
        }
        return new Response("game server unavailable", { status: 503 });
      }
    }
    return handler.fetch(request, env, ctx);
  },
} satisfies ExportedHandler<Env>;

// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
export { BucketCachePurge, DOQueueHandler, DOShardedTagCache } from "./.open-next/worker.js";
